    #[test]
    fn der_refuses_every_encoding_the_rules_forbid() {
        let cases: &[(&[u8], &str)] = &[
            (&[0x30, 0x80, 0x00, 0x00], "ED002"),
            (&[0x30, 0x81, 0x00], "ED004"),
            (&[0x30, 0x81, 0x01, 0x00], "ED005"),
            (&[0x1f, 0x01, 0x00], "ED001"),
            (&[0x30, 0x05, 0x00], "ED007"),
        ];
        for (bytes, code) in cases {
            let mut reader = super::der::Reader::new(bytes, 0);
            let error = reader.next_element().unwrap_err();
            assert_eq!(error.code, *code, "{bytes:?}");
        }

        let padded = super::der::Element {
            tag: super::der::tag::INTEGER,
            contents: &[0x00, 0x01],
            offset: 0,
            total: 4,
        };
        assert_eq!(
            super::der::read_integer_bytes(&padded).unwrap_err().code,
            "ED032"
        );
    }

    #[test]
    fn der_reads_object_identifiers_the_way_the_encoding_defines_them() {
        let cases: &[(&[u8], &str)] = &[
            (&[0x06, 0x03, 0x55, 0x04, 0x03], "2.5.4.3"),
            (
                &[
                    0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b,
                ],
                "1.2.840.113549.1.1.11",
            ),
            (
                &[0x06, 0x07, 0x2a, 0x86, 0x48, 0xce, 0x3d, 0x04, 0x03],
                "1.2.840.10045.4.3",
            ),
        ];
        for (bytes, expected) in cases {
            let mut reader = super::der::Reader::new(bytes, 0);
            let element = reader.next_element().unwrap();
            assert_eq!(super::der::read_oid(&element).unwrap(), *expected);
        }

        for bad in [
            &[0x06u8, 0x02, 0x55, 0x80][..],
            &[0x06, 0x03, 0x55, 0x80, 0x01][..],
        ] {
            let mut reader = super::der::Reader::new(bad, 0);
            let element = reader.next_element().unwrap();
            assert!(super::der::read_oid(&element).is_err(), "{bad:?}");
        }
    }

    #[test]
    fn der_survives_arbitrary_input() {
        let mut seed = 0xaaaa_5555_cccc_3333u64;
        for _ in 0..3_000 {
            let length = (xorshift(&mut seed) % 120) as usize;
            let bytes: Vec<u8> = (0..length)
                .map(|_| (xorshift(&mut seed) & 0xff) as u8)
                .collect();
            let mut reader = super::der::Reader::new(&bytes, 0);
            for _ in 0..64 {
                match reader.next_element() {
                    Ok(element) => {
                        assert!(element.contents.len() <= bytes.len());
                        let _ = super::der::read_oid(&element);
                        let _ = super::der::read_string(&element);
                        let _ = super::der::read_integer_bytes(&element);
                    }
                    Err(_) => break,
                }
                if reader.is_empty() {
                    break;
                }
            }
        }
    }

    #[test]
    fn a_certificate_reads_as_the_tools_read_it() {
        let certificate = Certificate::parse(CONFORMANCE_CERTIFICATE).expect("must parse");

        assert_eq!(certificate.subject, "C=TR, O=Omni, CN=Omni Conformance");
        assert_eq!(certificate.issuer, certificate.subject, "it is self-signed");
        assert_eq!(certificate.serial, "5D97B82E9226CBB1");
        assert_eq!(certificate.public_key_algorithm.display(), "RSA");
        assert_eq!(certificate.public_key_bits, Some(2048));
        assert!(certificate.signature_algorithm.is_known());

        assert_eq!(
            certificate.fingerprint.to_hex(),
            "a7259d236ba6819af41ef78ed77ed17804f07ec9edce8294a5ff380558289fbe"
        );
        assert!(certificate
            .fingerprint_display()
            .starts_with("A7:25:9D:23:6B:A6:81:9A"));

        assert!(certificate.not_before.ends_with("UTC"));
        assert!(certificate.not_after > certificate.not_before);
    }

    #[test]
    fn a_certificate_never_claims_its_signature_was_checked() {
        let certificate = Certificate::parse(CONFORMANCE_CERTIFICATE).unwrap();
        let mut w = Writer::new();
        w.begin_array(None);
        certificate.write_json(&mut w);
        w.end_array();
        let document = w.finish();

        assert!(is_structurally_valid(&document));
        assert!(document.contains("\"signatureChecked\":false"));
    }

    #[test]
    fn a_damaged_certificate_is_refused_rather_than_half_read() {
        let mut sink_count = 0;
        for position in [0usize, 1, 4, 40, 200, 500] {
            let mut damaged = CONFORMANCE_CERTIFICATE.to_vec();
            damaged[position] ^= 0xff;
            if Certificate::parse(&damaged).is_err() {
                sink_count += 1;
            }
        }
        assert!(sink_count > 0, "damaging a certificate must be noticed");

        assert!(Certificate::parse(&[]).is_err());
        assert!(Certificate::parse(&[0x30, 0x00]).is_err());
        assert!(Certificate::parse(&CONFORMANCE_CERTIFICATE[..100]).is_err());
    }

    #[test]
    fn certificate_parsing_survives_arbitrary_input() {
        let mut seed = 0x9999_1111_2222_3333u64;
        for _ in 0..2_000 {
            let mut bytes = CONFORMANCE_CERTIFICATE.to_vec();
            let mutations = (xorshift(&mut seed) % 8) + 1;
            for _ in 0..mutations {
                let position = (xorshift(&mut seed) as usize) % bytes.len();
                bytes[position] = (xorshift(&mut seed) & 0xff) as u8;
            }
            let _ = Certificate::parse(&bytes);
        }
    }

    #[test]
    fn a_package_without_a_signing_block_is_reported_as_such() {
        let mut builder = ArchiveBuilder::new();
        builder.add("a.txt", b"x".to_vec()).unwrap();
        let bytes = builder.finish().unwrap();
        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();

        let mut sink = Sink::new();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(!report.has_block);
        assert!(!report.everything_checkable_passed());
        assert!(sink.entries().iter().any(|d| d.code == "ES030"));
    }

    fn find_build_tool(tool: &str) -> Option<std::path::PathBuf> {
        find_apksigner().and_then(|path| {
            let candidate = path.parent()?.join(tool);
            candidate.is_file().then_some(candidate)
        })
    }

    pub(crate) fn find_apksigner() -> Option<std::path::PathBuf> {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for name in ["ANDROID_HOME", "ANDROID_SDK_ROOT"] {
            if let Ok(value) = std::env::var(name) {
                if !value.is_empty() {
                    roots.push(std::path::PathBuf::from(value));
                }
            }
        }
        roots.push(std::path::PathBuf::from("/opt/android-sdk"));
        roots.push(std::path::PathBuf::from("/usr/local/lib/android/sdk"));
        if let Ok(home) = std::env::var("HOME") {
            roots.push(std::path::PathBuf::from(home).join("Android/Sdk"));
        }

        for root in roots {
            let Ok(entries) = std::fs::read_dir(root.join("build-tools")) else {
                continue;
            };
            let mut versions: Vec<std::path::PathBuf> = entries
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.path())
                .collect();
            versions.sort();
            for version in versions.into_iter().rev() {
                let candidate = version.join("apksigner");
                if candidate.is_file() {
                    return Some(candidate);
                }
            }
        }

        assert!(
            std::env::var("OMNI_REQUIRE_APKSIGNER").is_err(),
            "OMNI_REQUIRE_APKSIGNER is set but no apksigner was found, so the \
             signing conformance tests would have skipped silently"
        );
        None
    }

    fn sign_with_apksigner(label: &str) -> Option<(Vec<u8>, std::path::PathBuf)> {
        sign_with_apksigner_using(label, 2048)
    }

    fn sign_with_apksigner_using(
        label: &str,
        key_bits: u32,
    ) -> Option<(Vec<u8>, std::path::PathBuf)> {
        let apksigner = find_apksigner()?;

        let directory = temp_directory(label);
        let apk = directory.join("sample.apk");
        let keystore = directory.join("k.jks");

        let mut builder = ArchiveBuilder::for_android();
        builder
            .add("AndroidManifest.xml", b"<manifest/>".to_vec())
            .unwrap();
        builder.add("classes.dex", vec![0x2a; 3_000]).unwrap();
        builder
            .add("lib/arm64-v8a/libomni.so", vec![0x7f; 2_000])
            .unwrap();
        std::fs::write(&apk, builder.finish().unwrap()).unwrap();

        let keytool = std::process::Command::new("keytool")
            .args([
                "-genkeypair",
                "-keystore",
                keystore.to_str().unwrap(),
                "-storepass",
                "pass123",
                "-keypass",
                "pass123",
                "-alias",
                "k",
                "-keyalg",
                "RSA",
                "-keysize",
                &key_bits.to_string(),
                "-validity",
                "30",
                "-dname",
                "CN=Omni Test, O=Omni, C=TR",
            ])
            .output()
            .ok()?;
        if !keytool.status.success() {
            std::fs::remove_dir_all(&directory).ok();
            return None;
        }

        let signed = std::process::Command::new(&apksigner)
            .args([
                "sign",
                "--ks",
                keystore.to_str().unwrap(),
                "--ks-pass",
                "pass:pass123",
                "--key-pass",
                "pass:pass123",
                "--ks-key-alias",
                "k",
                "--v1-signing-enabled",
                "false",
                "--v2-signing-enabled",
                "true",
                "--v3-signing-enabled",
                "false",
                "--min-sdk-version",
                &crate::compiler::OLDEST_API.to_string(),
                apk.to_str().unwrap(),
            ])
            .output()
            .ok()?;
        assert!(
            signed.status.success(),
            "apksigner failed: {}",
            String::from_utf8_lossy(&signed.stderr)
        );

        let bytes = std::fs::read(&apk).unwrap();
        Some((bytes, directory))
    }

    #[test]
    fn the_digest_this_build_computes_matches_the_one_apksigner_wrote() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-digest") else {
            eprintln!(
                "signing conformance: apksigner is not available here, so the digest \
                 was not checked against it"
            );
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the signed package must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(
            report.has_block,
            "apksigner wrote a block and it was not found"
        );
        assert!(
            report.schemes.contains(&"v2"),
            "schemes: {:?}",
            report.schemes
        );
        assert_eq!(report.signers.len(), 1);
        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert!(
            report.digests_verified > 0,
            "no digest was recomputed: {:?}",
            sink.entries()
        );
        assert!(report.everything_checkable_passed());

        let certificate = &report.signers[0].certificates[0];
        assert_eq!(certificate.subject, "C=TR, O=Omni, CN=Omni Test");
        assert_eq!(certificate.public_key_bits, Some(2048));

        assert!(!report.signatures_checked);

        eprintln!(
            "signing conformance: {} digest(s) recomputed and matched apksigner",
            report.digests_verified
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    /// The package this build wrote. There is one variant, so there is one
    /// directory to look in; a signed package is preferred over the unsigned
    /// one beside it, which is what a build without signing secrets leaves.
    fn built_package() -> Option<std::path::PathBuf> {
        let mut found: Vec<std::path::PathBuf> =
            std::fs::read_dir("Builder/build/outputs/apk/release")
                .ok()?
                .filter_map(|entry| Some(entry.ok()?.path()))
                .filter(|path| path.extension().is_some_and(|end| end == "apk"))
                .collect();
        found.sort();
        found
            .iter()
            .find(|path| !path.to_string_lossy().ends_with("-unsigned.apk"))
            .or_else(|| found.first())
            .cloned()
    }

    fn package_this_build_produced() -> Option<Vec<u8>> {
        if let Ok(named) = std::env::var("OMNI_PACKAGE_UNDER_TEST") {
            if !named.is_empty() {
                let bytes = std::fs::read(&named)
                    .unwrap_or_else(|why| panic!("OMNI_PACKAGE_UNDER_TEST={named}: {why}"));
                return Some(bytes);
            }
        }
        std::fs::read(built_package()?).ok()
    }

    #[test]
    fn the_package_this_build_produced_reads_and_its_digest_holds() {
        let Some(bytes) = package_this_build_produced() else {
            eprintln!(
                "signing conformance: no built package here, so a real Android \
                 Gradle Plugin package was not read. Build one with \
                 `./gradlew :Builder:assembleRelease` or set \
                 OMNI_PACKAGE_UNDER_TEST."
            );
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the package must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert!(
            archive.entries().len() > 10,
            "a real package has more than a handful of entries"
        );

        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        // A build given no signing key leaves the package unsigned, and the
        // reader has to say so rather than find a block that is not there.
        // Where a key was given, every digest in the block it wrote has to come
        // back matching.
        if !report.has_block {
            assert_eq!(report.digests_verified, 0, "{:?}", sink.entries());
            assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
            assert!(report.schemes.is_empty(), "{:?}", report.schemes);
            eprintln!(
                "signing conformance: {} entries, and no signature — this build \
                 was given no key, so the package it wrote cannot be installed",
                archive.entries().len()
            );
            return;
        }

        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert!(report.digests_verified > 0, "{:?}", sink.entries());
        assert!(!report.signatures_checked);

        eprintln!(
            "signing conformance: {} entries, schemes {:?}, {} digest(s) matched",
            archive.entries().len(),
            report.schemes,
            report.digests_verified
        );
    }

    #[test]
    fn a_sha512_signed_package_is_checked_rather_than_declined() {
        let Some((bytes, directory)) = sign_with_apksigner_using("v2-sha512", 4096) else {
            eprintln!("signing conformance: apksigner is not available here");
            return;
        };

        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).expect("the signed package must read");
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        let algorithms: Vec<&str> = report
            .signers
            .iter()
            .flat_map(|signer| signer.digests.iter().map(|(a, _)| a.name))
            .collect();
        assert!(
            algorithms.iter().any(|name| name.contains("SHA-512")),
            "expected a SHA-512 signature, got {algorithms:?}"
        );
        assert_eq!(report.digests_failed, 0, "{:?}", sink.entries());
        assert_eq!(
            report.digests_unverifiable,
            0,
            "nothing here should be undecidable any more: {:?}",
            sink.entries()
        );
        assert!(report.digests_verified > 0, "{:?}", sink.entries());
        assert_eq!(
            report.signers[0].certificates[0].public_key_bits,
            Some(4096)
        );
        assert!(!report.signatures_checked);

        eprintln!(
            "signing conformance: SHA-512, {} digest(s) recomputed and matched apksigner",
            report.digests_verified
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_verity_digest_is_never_compared_against_the_chunked_one() {
        for id in [0x0421u32, 0x0423, 0x0425] {
            let algorithm = signing::algorithm(id).expect("a defined algorithm");
            assert_eq!(
                algorithm.digest,
                signing::DigestKind::VerityMerkle,
                "0x{id:04x} ({}) must not be treated as a chunked digest",
                algorithm.name
            );
        }

        for (id, kind) in [
            (0x0101u32, signing::DigestKind::Chunked256),
            (0x0102, signing::DigestKind::Chunked512),
            (0x0103, signing::DigestKind::Chunked256),
            (0x0104, signing::DigestKind::Chunked512),
            (0x0201, signing::DigestKind::Chunked256),
            (0x0202, signing::DigestKind::Chunked512),
            (0x0301, signing::DigestKind::Chunked256),
        ] {
            assert_eq!(signing::algorithm(id).unwrap().digest, kind, "0x{id:04x}");
        }
    }

    #[test]
    fn changing_one_byte_of_a_signed_package_is_detected() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-tamper") else {
            eprintln!("signing conformance: apksigner is not available here");
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let entry = archive.entry("classes.dex").expect("classes.dex");
        let position = entry.data_offset as usize + 10;

        let mut tampered = bytes.clone();
        tampered[position] ^= 0xff;

        let mut sink = Sink::new();
        let archive = archive::read(&tampered, &mut sink).unwrap();
        let report = signing::examine(
            &tampered,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );

        assert!(report.has_block);
        assert_eq!(report.digests_verified, 0);
        assert!(report.digests_failed > 0, "a changed byte must be noticed");
        assert!(!report.everything_checkable_passed());

        let error = sink.entries().iter().find(|d| d.code == "ES033").unwrap();
        assert_eq!(error.severity, Severity::Fatal);
        assert_eq!(error.class, FailureClass::Corruption);
        assert!(error.suggestion.as_deref().unwrap().contains("Do not"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_signing_report_says_what_it_did_not_check() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-report") else {
            return;
        };

        let archive = archive::read(&bytes, &mut Sink::new()).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut Sink::new(),
        );

        let mut w = Writer::new();
        w.begin_object(None);
        report.write_json(&mut w, "signing");
        w.end_object();
        let document = w.finish();

        assert!(is_structurally_valid(&document), "{document}");
        assert!(document.contains("\"signaturesChecked\":false"));
        assert!(document.contains("does not prove who wrote it"));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_signing_block_reader_survives_arbitrary_input() {
        let Some((bytes, directory)) = sign_with_apksigner("v2-fuzz") else {
            return;
        };

        let mut seed = 0x7777_8888_9999_aaaau64;
        for _ in 0..1_500 {
            let mut damaged = bytes.clone();
            let mutations = (xorshift(&mut seed) % 6) + 1;
            for _ in 0..mutations {
                let position = (xorshift(&mut seed) as usize) % damaged.len();
                damaged[position] = (xorshift(&mut seed) & 0xff) as u8;
            }

            let mut sink = Sink::new();
            if let Some(archive) = archive::read(&damaged, &mut sink) {
                let report = signing::examine(
                    &damaged,
                    archive.central_directory_offset(),
                    archive.end_record_offset(),
                    &mut sink,
                );
                assert!(!report.signatures_checked);
            }
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn no_text_the_interface_shows_carries_a_stray_run_of_spaces() {
        let check = |what: &str, text: &str| {
            assert!(
                !text.contains("  "),
                "{what} carries a run of spaces: {text:?}"
            );
        };

        for subsystem in super::SUBSYSTEMS {
            check(subsystem.name, subsystem.name);
            check(subsystem.name, subsystem.summary);
            for missing in subsystem.missing {
                check(subsystem.name, missing);
            }
        }
        for dependency in super::BOOTSTRAP_DEPENDENCIES {
            check(dependency, dependency);
        }
        for plugin in super::plugin::Registry::builtin().all() {
            let contract = plugin.contract();
            check(contract.id, contract.summary);
            for note in contract.non_responsibilities {
                check(contract.id, note);
            }
        }
    }

    fn minimal_dex(version: &[u8; 3]) -> Vec<u8> {
        let mut data = vec![0u8; dex::HEADER_SIZE as usize];
        data[0..4].copy_from_slice(dex::MAGIC);
        data[4..7].copy_from_slice(version);
        data[7] = 0;
        data[32..36].copy_from_slice(&(dex::HEADER_SIZE).to_le_bytes());
        data[36..40].copy_from_slice(&dex::HEADER_SIZE.to_le_bytes());
        data[40..44].copy_from_slice(&dex::ENDIAN_CONSTANT.to_le_bytes());
        seal_dex(&mut data);
        data
    }

    fn seal_dex(data: &mut [u8]) {
        let signature = super::hash::sha1(&data[32..]);
        data[12..32].copy_from_slice(signature.as_bytes());
        let checksum = super::binary::checksum::adler32(&data[12..]);
        data[8..12].copy_from_slice(&checksum.to_le_bytes());
    }

    #[test]
    fn an_empty_dex_reads_and_holds_its_own_fields() {
        let data = minimal_dex(b"035");
        let mut sink = Sink::new();
        let file = dex::read(&data, &mut sink).expect("a well-formed DEX must read");

        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert_eq!(sink.entries().len(), 0, "{:?}", sink.entries());
        assert_eq!(file.header.version, "035");
        assert_eq!(file.header.file_size, dex::HEADER_SIZE);
        assert!(file.classes.is_empty());
        assert!(file.strings.is_empty());

        let integrity = dex::integrity(&data).unwrap();
        assert!(integrity.checksum_matches());
        assert!(integrity.signature_matches());
        assert!(integrity.self_consistent());
    }

    #[test]
    fn a_dex_header_is_checked_before_it_is_believed() {
        type Damage = fn(&mut Vec<u8>);

        let cases: &[(&str, Damage)] = &[
            ("EX004", |d| {
                d[40..44].copy_from_slice(&dex::REVERSE_ENDIAN_CONSTANT.to_le_bytes());
                seal_dex(d);
            }),
            ("EX004", |d| {
                d[40..44].copy_from_slice(&0xdead_beefu32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX005", |d| {
                d[36..40].copy_from_slice(&0x80u32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX006", |d| {
                d[32..36].copy_from_slice(&9_999u32.to_le_bytes());
                seal_dex(d);
            }),
            ("EX007", |d| {
                d[56..60].copy_from_slice(&0xffff_ffffu32.to_le_bytes());
                seal_dex(d);
            }),
        ];

        for (code, damage) in cases {
            let mut data = minimal_dex(b"035");
            damage(&mut data);
            let error = dex::read(&data, &mut Sink::new())
                .expect_err("a header this wrong must be refused");
            assert_eq!(error.code, *code, "message: {}", error.message);
        }
    }

    #[test]
    fn a_dex_that_is_not_one_is_refused_immediately() {
        for bad in [
            &b""[..],
            &b"dex"[..],
            &b"not a dex file at all"[..],
            &b"dex\n035\0"[..],
        ] {
            assert!(
                dex::read(bad, &mut Sink::new()).is_err(),
                "{:?} must be refused",
                String::from_utf8_lossy(bad)
            );
        }
    }

    #[test]
    fn changing_one_byte_of_a_dex_is_reported_but_not_hidden() {
        let mut data = minimal_dex(b"035");
        data[dex::HEADER_SIZE as usize - 1] ^= 0xff;

        let mut sink = Sink::new();
        let file = dex::read(&data, &mut sink);
        assert!(file.is_ok(), "a damaged DEX still reads");

        let codes: Vec<&str> = sink.entries().iter().map(|d| d.code.as_str()).collect();
        assert!(codes.contains(&"EX020"), "checksum: {codes:?}");
        assert!(codes.contains(&"EX021"), "signature: {codes:?}");

        let integrity = dex::integrity(&data).unwrap();
        assert!(!integrity.self_consistent());
    }

    #[test]
    fn integrity_is_never_reported_as_more_than_it_is() {
        let data = minimal_dex(b"035");
        let integrity = dex::integrity(&data).unwrap();

        let mut w = Writer::new();
        w.begin_object(None);
        integrity.write_json(&mut w, "integrity");
        w.end_object();
        let document = w.finish();

        assert!(is_structurally_valid(&document));
        assert!(document.contains("\"checksumMatches\":true"));
        assert!(document.contains("not evidence of authorship or authenticity"));
        assert!(document.contains("SHA-1 is broken for collision resistance"));
    }

    #[test]
    fn type_descriptors_become_the_names_a_person_writes() {
        let cases = [
            ("Ljava/lang/String;", "java.lang.String"),
            ("Lcom/omni/builder/Builder;", "com.omni.builder.Builder"),
            ("V", "void"),
            ("I", "int"),
            ("J", "long"),
            ("Z", "boolean"),
            ("B", "byte"),
            ("S", "short"),
            ("C", "char"),
            ("F", "float"),
            ("D", "double"),
            ("[I", "int[]"),
            ("[[Ljava/lang/String;", "java.lang.String[][]"),
        ];
        for (descriptor, expected) in cases {
            assert_eq!(
                dex::descriptor_to_source(descriptor),
                expected,
                "{descriptor}"
            );
        }

        for odd in ["", "Ljava/lang/String", "Q", "L;x"] {
            assert_eq!(dex::descriptor_to_source(odd), odd, "{odd:?}");
        }
    }

    #[test]
    fn modified_utf8_is_decoded_the_way_the_formats_define_it() {
        assert_eq!(modified_utf8::decode(b"Builder").unwrap(), "Builder");

        assert_eq!(modified_utf8::decode(&[0xc0, 0x80]).unwrap(), "\0");

        assert_eq!(modified_utf8::decode("çğü".as_bytes()).unwrap(), "çğü");
        assert_eq!(modified_utf8::decode("→".as_bytes()).unwrap(), "→");

        let rocket = [0xed, 0xa0, 0xbd, 0xed, 0xb2, 0x80];
        assert_eq!(modified_utf8::decode(&rocket).unwrap(), "\u{1f480}");

        assert!(modified_utf8::decode(&[0xf0, 0x9f, 0x92, 0x80]).is_err());
    }

    #[test]
    fn a_broken_string_is_refused_rather_than_repaired() {
        let cases: &[(&[u8], &str)] = &[
            (&[0xed, 0xa0, 0xbd], "E7053"),
            (&[0xed, 0xb2, 0x80], "E7053"),
            (&[0xc2], "E7050"),
            (&[0xe2, 0x86], "E7050"),
            (&[0xc2, 0x41], "E7051"),
            (&[0xf0, 0x9f, 0x92, 0x80], "E7052"),
        ];
        for (bytes, code) in cases {
            let error =
                modified_utf8::decode(bytes).expect_err(&format!("{bytes:?} must be refused"));
            assert_eq!(error.code, *code, "{bytes:?}");
        }
    }

    #[test]
    fn the_dex_reader_survives_arbitrary_input() {
        let mut seed = 0x1dea_7c0f_fee5_1234u64;
        for _ in 0..3_000 {
            let length = (xorshift(&mut seed) % 400) as usize;
            let mut data: Vec<u8> = (0..length)
                .map(|_| (xorshift(&mut seed) & 0xff) as u8)
                .collect();

            if length >= 8 && xorshift(&mut seed).is_multiple_of(2) {
                data[0..4].copy_from_slice(dex::MAGIC);
                data[4..8].copy_from_slice(b"035\0");
            }

            let mut sink = Sink::new();
            let _ = dex::read(&data, &mut sink);
            let _ = dex::integrity(&data);
            let _ = modified_utf8::decode(&data);
        }
    }

    fn dex_conformance_may_skip(why: &str) {
        assert!(
            std::env::var("OMNI_REQUIRE_DEX_CONFORMANCE").is_err(),
            "OMNI_REQUIRE_DEX_CONFORMANCE is set but the DEX conformance test \
             would have skipped: {why}"
        );
    }

    fn dex_this_build_produced() -> Option<Vec<u8>> {
        let Some(apk) = built_package() else {
            dex_conformance_may_skip("no APK has been built");
            return None;
        };

        let output = std::process::Command::new("unzip")
            .args(["-p", &apk.to_string_lossy(), "classes.dex"])
            .output()
            .ok()?;
        if !output.status.success() || output.stdout.is_empty() {
            dex_conformance_may_skip("classes.dex could not be read out of the APK");
            return None;
        }
        Some(output.stdout)
    }

    fn dexdump(bytes: &[u8]) -> Option<(std::collections::BTreeMap<String, String>, Vec<String>)> {
        let Some(tool) = find_apksigner().and_then(|p| Some(p.parent()?.join("dexdump"))) else {
            dex_conformance_may_skip("no Android SDK build-tools were found");
            return None;
        };
        if !tool.is_file() {
            dex_conformance_may_skip("dexdump is not in the build-tools found");
            return None;
        }

        let directory = temp_directory("dexdump");
        let path = directory.join("classes.dex");
        std::fs::write(&path, bytes).ok()?;

        let output = std::process::Command::new(&tool)
            .args(["-f", path.to_str()?])
            .output()
            .ok()?;
        std::fs::remove_dir_all(&directory).ok();
        if !output.status.success() {
            return None;
        }

        let text = String::from_utf8_lossy(&output.stdout).to_string();
        let mut fields = std::collections::BTreeMap::new();
        let mut classes = Vec::new();
        for line in text.lines() {
            let Some((left, right)) = line.split_once(':') else {
                continue;
            };
            let key = left.trim();
            let value = right.trim();
            if key == "Class descriptor" {
                classes.push(value.trim_matches('\'').to_string());
            } else if !key.contains(' ') || key.contains('_') || key == "magic" {
                fields.insert(key.to_string(), value.to_string());
            }
        }
        Some((fields, classes))
    }

    #[test]
    fn the_dex_this_build_produced_reads_as_dexdump_reads_it() {
        let Some(bytes) = dex_this_build_produced() else {
            eprintln!(
                "dex conformance: no built package here, so nothing was read. \
                 Build one with `./gradlew :Builder:assembleRelease`."
            );
            return;
        };
        let Some((fields, descriptors)) = dexdump(&bytes) else {
            eprintln!("dex conformance: dexdump is not available here");
            return;
        };

        let mut sink = Sink::new();
        let file = dex::read(&bytes, &mut sink).expect("a real classes.dex must read");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        assert_eq!(
            sink.entries().len(),
            0,
            "a package this build produced must be intact: {:?}",
            sink.entries()
        );

        let number = |key: &str| -> u32 {
            let raw = fields
                .get(key)
                .unwrap_or_else(|| panic!("dexdump printed no {key}"));
            raw.split_whitespace()
                .next()
                .unwrap()
                .parse()
                .unwrap_or_else(|_| panic!("{key} = {raw:?}"))
        };

        assert_eq!(fields.get("magic").unwrap(), "'dex\\n039\\0'");
        assert_eq!(file.header.version, "039");
        assert_eq!(file.header.file_size, number("file_size"));
        assert_eq!(file.header.header_size, number("header_size"));
        assert_eq!(file.header.string_ids_size, number("string_ids_size"));
        assert_eq!(file.header.type_ids_size, number("type_ids_size"));
        assert_eq!(file.header.proto_ids_size, number("proto_ids_size"));
        assert_eq!(file.header.field_ids_size, number("field_ids_size"));
        assert_eq!(file.header.method_ids_size, number("method_ids_size"));
        assert_eq!(file.header.class_defs_size, number("class_defs_size"));

        assert_eq!(file.strings.len(), file.header.string_ids_size as usize);
        assert_eq!(file.types.len(), file.header.type_ids_size as usize);
        assert_eq!(file.fields.len(), file.header.field_ids_size as usize);
        assert_eq!(file.methods.len(), file.header.method_ids_size as usize);
        assert_eq!(file.classes.len(), file.header.class_defs_size as usize);

        let expected: Vec<String> = descriptors
            .iter()
            .map(|d| dex::descriptor_to_source(d))
            .collect();
        assert_eq!(file.class_names(), expected);

        let integrity = dex::integrity(&bytes).unwrap();
        assert!(integrity.checksum_matches());
        assert!(integrity.signature_matches());

        eprintln!(
            "dex conformance: {} classes, {} methods, {} strings; header and class \
             list agree with dexdump",
            file.classes.len(),
            file.methods.len(),
            file.strings.len()
        );
    }

    fn minimal_class(long_first: bool) -> Vec<u8> {
        let mut pool: Vec<u8> = Vec::new();
        let mut next = 1u16;

        if long_first {
            pool.push(5);
            pool.extend_from_slice(&1_234_567_890_123u64.to_be_bytes());
            next += 2;
        }

        let name_index = next;
        pool.push(1);
        pool.extend_from_slice(&4u16.to_be_bytes());
        pool.extend_from_slice(b"Test");
        next += 1;

        let this_index = next;
        pool.push(7);
        pool.extend_from_slice(&name_index.to_be_bytes());
        next += 1;

        let object_name_index = next;
        pool.push(1);
        pool.extend_from_slice(&16u16.to_be_bytes());
        pool.extend_from_slice(b"java/lang/Object");
        next += 1;

        let super_index = next;
        pool.push(7);
        pool.extend_from_slice(&object_name_index.to_be_bytes());
        next += 1;

        let mut data: Vec<u8> = Vec::new();
        data.extend_from_slice(&jvm::MAGIC.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&61u16.to_be_bytes());
        data.extend_from_slice(&next.to_be_bytes());
        data.extend_from_slice(&pool);
        data.extend_from_slice(&0x0021u16.to_be_bytes());
        data.extend_from_slice(&this_index.to_be_bytes());
        data.extend_from_slice(&super_index.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data.extend_from_slice(&0u16.to_be_bytes());
        data
    }

