    fn call_ffi(f: impl FnOnce() -> *mut std::os::raw::c_char) -> String {
        unsafe {
            let raw = f();
            assert!(!raw.is_null(), "the bridge must always report");
            let text = std::ffi::CStr::from_ptr(raw).to_str().unwrap().to_string();
            super::ffi::omni_string_free(raw);
            text
        }
    }

    #[test]
    fn the_java_somebody_wrote_can_call_into_the_platform_it_was_handed() {
        // The whole point of a dependency: the person imports what they like
        // and it compiles. Nothing here is in the compiler's own table -- a
        // SharedPreferences, a Handler, a generic ArrayAdapter, a date format
        // -- and all of it comes from the platform jar.
        let Some(platform) = super::builder::platform_jar() else {
            eprintln!("java: no android.jar on this machine to call into");
            return;
        };

        let directory = temp_directory("omni-java-platform");
        let root = directory.join("Called");
        let spec =
            "package=com.tr.yt;label=Called;abis=arm64-v8a;minSdk=30;targetSdk=36;languages=java";
        super::scaffold::create(
            root.to_str().unwrap(),
            &super::scaffold::Spec::parse(spec).unwrap(),
        )
        .expect("the project must be created");

        let source = r#"
package com.tr.yt;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.os.Handler;
import android.os.Looper;
import android.util.Log;
import android.widget.ArrayAdapter;
import android.widget.ListView;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Calendar;
import java.util.List;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicInteger;

public final class MainActivity extends Activity {

    private final AtomicInteger counted = new AtomicInteger();
    private SharedPreferences settings;
    private Handler onTheMainThread;

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        settings = getSharedPreferences("called", MODE_PRIVATE);
        onTheMainThread = new Handler(Looper.getMainLooper());

        List<String> rows = new ArrayList<String>();
        rows.add(stamped());
        ArrayAdapter<String> adapter =
            new ArrayAdapter<String>(this, android.R.layout.simple_list_item_1, rows);
        ListView list = new ListView(this);
        list.setAdapter(adapter);
        setContentView(list);

        Log.i("Called", rows.get(0));
    }

    String stamped() {
        SimpleDateFormat shape = new SimpleDateFormat("yyyy-MM-dd", Locale.US);
        return shape.format(Calendar.getInstance().getTime());
    }

    int remember(String key) {
        int held = counted.incrementAndGet();
        settings.edit().putInt(key, held).apply();
        return held;
    }
}
"#;
        std::fs::write(
            root.join(super::scaffold::JAVA_FOLDER)
                .join("MainActivity.java"),
            source,
        )
        .unwrap();

        let project = super::builder::from_project(root.to_str().unwrap())
            .expect("calling into the platform must build");
        let names: Vec<&str> = project
            .code
            .iter()
            .map(|one| one.descriptor.as_str())
            .collect();
        assert!(names.contains(&"Lcom/tr/yt/MainActivity;"), "{names:?}");

        // And the call really is the platform's, with the descriptor the
        // device will check it against.
        let activity = project
            .code
            .iter()
            .find(|one| one.descriptor == "Lcom/tr/yt/MainActivity;")
            .unwrap();
        let called: Vec<String> = activity
            .virtual_methods
            .iter()
            .chain(activity.direct_methods.iter())
            .flat_map(|one| one.instructions.iter())
            .filter_map(|one| match &one.operand {
                super::dexwrite::Operand::Method(held) => {
                    Some(format!("{}.{}", held.class, held.name))
                }
                _ => None,
            })
            .collect();
        for wanted in [
            "Landroid/content/SharedPreferences;.edit",
            "Landroid/os/Handler;.<init>",
            // Declared on DateFormat and inherited, which is the class the
            // call names -- the same one `javac` writes.
            "Ljava/text/DateFormat;.format",
            "Landroid/content/SharedPreferences$Editor;.apply",
            "Ljava/util/concurrent/atomic/AtomicInteger;.incrementAndGet",
        ] {
            assert!(
                called.iter().any(|one| one == wanted),
                "{wanted} is missing from {called:?}"
            );
        }

        // A project with no jar of its own still built, against the platform
        // this machine has.
        let _ = platform;
        let _ = directory;
    }

    #[test]
    fn the_java_somebody_wrote_can_name_the_resources_the_project_holds() {
        // `R.string.app_name` is the first line of Android anybody writes.
        // The class behind it is not on disk and never was: it is written from
        // the identifiers the resource table hands out, and compiled with
        // everything else.
        let directory = temp_directory("omni-java-resources");
        let root = directory.join("Named");
        let spec =
            "package=com.tr.yt;label=Named;abis=arm64-v8a;minSdk=30;targetSdk=36;languages=java";
        super::scaffold::create(
            root.to_str().unwrap(),
            &super::scaffold::Spec::parse(spec).unwrap(),
        )
        .expect("the project must be created");

        let source = r#"
package com.tr.yt;

import android.app.Activity;
import android.os.Bundle;

public final class MainActivity extends Activity {
    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        setTitle(getString(R.string.app_name));
    }

    public int named() {
        return R.string.app_name;
    }
}
"#;
        std::fs::write(
            root.join(super::scaffold::JAVA_FOLDER)
                .join("MainActivity.java"),
            source,
        )
        .unwrap();

        let project = super::builder::from_project(root.to_str().unwrap())
            .expect("naming a resource must build");
        let names: Vec<&str> = project
            .code
            .iter()
            .map(|one| one.descriptor.as_str())
            .collect();
        assert!(names.contains(&"Lcom/tr/yt/R$string;"), "{names:?}");
        assert!(names.contains(&"Lcom/tr/yt/MainActivity;"), "{names:?}");

        // The number in the class is the number the table gives out, not a
        // guess -- an `R` that disagrees with the table is an application that
        // shows the wrong words or crashes looking for them.
        let mut sink = super::diag::Sink::new();
        let mut table =
            super::resources::Table::for_package(super::resources::APPLICATION_PACKAGE_ID);
        for (folder, text) in &project.values {
            let origin = format!("{}/{}", folder, super::scaffold::STRINGS_FILE);
            let config = super::resources::Config::parse_values_directory(folder).unwrap();
            assert!(table.read_values_for(text, &origin, config, &mut sink));
        }
        let compiled = table.compile(&mut sink).expect("the table must build");
        let wanted = compiled
            .id(super::resources::Kind::String, "app_name")
            .expect("app_name is declared");

        let held = project
            .code
            .iter()
            .find(|one| one.descriptor == "Lcom/tr/yt/R$string;")
            .unwrap();
        assert!(
            held.static_fields
                .iter()
                .any(|field| field.reference.name == "app_name"),
            "{:?}",
            held.static_fields
        );
        let said = super::builder::r_source("com.tr.yt", &compiled);
        assert!(
            said.contains(&format!("app_name = {};", wanted.raw() as i32)),
            "{said}"
        );

        let _ = directory;
    }

    #[test]
    fn the_java_somebody_wrote_is_the_code_the_package_carries() {
        // The whole way, with nothing hand-built in it: a project on disk, the
        // Java in its folder, compiled here, translated here, packed here, and
        // read back by the Android tool.
        let directory = temp_directory("omni-java-end-to-end");
        let root = directory.join("Written");
        let spec =
            "package=com.tr.yt;label=Written;abis=arm64-v8a;minSdk=30;targetSdk=36;languages=java";
        let made = super::scaffold::create(
            root.to_str().unwrap(),
            &super::scaffold::Spec::parse(spec).unwrap(),
        )
        .expect("the project must be created");
        assert!(!made.files.is_empty());

        // What the person writes, replacing the starter.
        let source = r#"
package com.tr.yt;

import android.app.Activity;
import android.os.Bundle;
import android.widget.TextView;

public final class MainActivity extends Activity {
    private int taps;
    private String label = "tapped ";

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        TextView view = new TextView(this);
        view.setText(describe());
        setContentView(view);
    }

    private String describe() {
        StringBuilder out = new StringBuilder();
        for (int one : counts()) {
            out.append(one);
            out.append(' ');
        }
        return label + taps + " of " + out.toString();
    }

    private int[] counts() {
        int[] found = new int[3];
        for (int i = 0; i < found.length; i++) {
            found[i] = i * taps;
        }
        return found;
    }

    public int classify(int value) {
        switch (value) {
            case 0: return 10;
            case 1: return 11;
            default: return -1;
        }
    }

    public String guarded(String text) {
        try {
            return text.substring(0, 2);
        } catch (IndexOutOfBoundsException e) {
            return "";
        } finally {
            taps++;
        }
    }
}
"#;
        let written = root
            .join(super::scaffold::JAVA_FOLDER)
            .join("MainActivity.java");
        std::fs::write(&written, source).unwrap();

        // A second file, so that more than one class reaches the package.
        std::fs::write(
            root.join(super::scaffold::JAVA_FOLDER).join("Counter.java"),
            "package com.tr.yt;\n\npublic final class Counter {\n    private int held;\n\n    public int next() {\n        held = held + 1;\n        return held;\n    }\n}\n",
        )
        .unwrap();

        let project = super::builder::from_project(root.to_str().unwrap())
            .expect("the project must load and compile");
        let names: Vec<&str> = project
            .code
            .iter()
            .map(|one| one.descriptor.as_str())
            .collect();
        assert!(
            names.contains(&"Lcom/tr/yt/MainActivity;"),
            "the activity somebody wrote has to be the one packed: {names:?}"
        );
        assert!(names.contains(&"Lcom/tr/yt/Counter;"), "{names:?}");

        let activity = project
            .code
            .iter()
            .find(|one| one.descriptor == "Lcom/tr/yt/MainActivity;")
            .unwrap();
        assert_eq!(activity.superclass, "Landroid/app/Activity;");
        let methods: Vec<&str> = activity
            .direct_methods
            .iter()
            .chain(activity.virtual_methods.iter())
            .map(|one| one.reference.name.as_str())
            .collect();
        for wanted in [
            "<init>", "onCreate", "describe", "counts", "classify", "guarded",
        ] {
            assert!(methods.contains(&wanted), "{methods:?}");
        }

        // And the package it comes to is one apksigner and dexdump accept.
        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_700_000_000, &mut sink)
            .expect("the package must build");
        assert!(outcome.carries_code);

        let read = super::archive::read(&outcome.package, &mut Sink::new()).unwrap();
        let entry = read
            .entry("classes.dex")
            .expect("the package carries a classes.dex");
        let dex = read.content(&outcome.package, entry).unwrap();

        let mut sink = Sink::new();
        let inside = super::dex::read(&dex, &mut sink).expect("our own reader must read it");
        assert!(
            inside.class_names().contains(&"com.tr.yt.MainActivity"),
            "{:?}",
            inside.class_names()
        );

        // Our own reader will read a dex that a device refuses. Asking dexdump
        // to disassemble makes it verify first, which is the difference.
        if let Some(tool) = find_build_tool("dexdump") {
            let written = directory.join("classes.dex");
            std::fs::write(&written, &dex).unwrap();
            let output = std::process::Command::new(&tool)
                .args(["-d", written.to_str().unwrap()])
                .output()
                .unwrap();
            let said = format!(
                "{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            assert!(output.status.success(), "dexdump refused it:\n{said}");
            assert!(said.contains("Lcom/tr/yt/MainActivity;"), "{said}");
            assert!(said.contains("packed-switch"), "the switch is in there");
            assert!(said.contains("move-exception"), "and so is the catch");
        }

        eprintln!(
            "java: a project's own Java, compiled and packed -- {} classes, a {} byte package",
            project.code.len(),
            outcome.package.len()
        );
    }

    #[test]
    fn a_whole_application_written_in_java_25_becomes_a_package_a_device_takes() {
        // Everything the compiler learned, in one application, taken the whole
        // way: written to a project on disk, compiled here, translated here,
        // packed and signed here, and then handed to the Android tools --
        // which verify before they will say a word about it.
        let directory = temp_directory("omni-whole-application");
        let root = directory.join("Whole");
        let spec =
            "package=com.tr.yt;label=Whole;abis=arm64-v8a;minSdk=30;targetSdk=36;languages=java";
        super::scaffold::create(
            root.to_str().unwrap(),
            &super::scaffold::Spec::parse(spec).unwrap(),
        )
        .expect("the project must be created");

        let folder = root.join(super::scaffold::JAVA_FOLDER);
        std::fs::write(
            folder.join("MainActivity.java"),
            r#"
package com.tr.yt;

import android.app.Activity;
import android.os.Bundle;
import android.util.Log;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.TextView;
import java.util.ArrayList;
import java.util.List;

public final class MainActivity extends Activity {
    private static final String TAG = "Whole";
    private static int made;

    static {
        made = 0;
    }

    private int taps;
    private String label = "tapped ";
    private final List seen = new ArrayList();
    private TextView view;

    {
        made = made + 1;
    }

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);

        LinearLayout holder = new LinearLayout(this);
        holder.setOrientation(1);

        view = new TextView(this);
        view.setText(greeting());
        holder.addView(view);

        Button tap = new Button(this);
        tap.setText("tap");
        tap.setOnClickListener(which -> {
            taps = taps + 1;
            seen.add(Integer.valueOf(taps));
            view.setText(describe());
        });
        holder.addView(tap);

        Button clear = new Button(this);
        clear.setText("clear");
        clear.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View which) {
                reset();
                view.setText(greeting());
            }
        });
        holder.addView(clear);

        setContentView(holder);
        Log.i(TAG, "started, made " + made);
    }

    private void reset() {
        taps = 0;
        seen.clear();
    }

    private String greeting() {
        return """
            Nothing yet.
            Tap to begin.
            """;
    }

    private String describe() {
        var out = new StringBuilder();
        out.append(label);
        out.append(taps);
        out.append(" (");
        out.append(Size.of(taps).name());
        out.append(") ");
        for (var one : counts()) {
            out.append(one);
            out.append(' ');
        }
        Point where = new Point(taps, taps * 2);
        out.append(where.toString());
        return out.toString();
    }

    private int[] counts() {
        int[] found = new int[3];
        for (int i = 0; i < found.length; i++) {
            found[i] = i * taps;
        }
        return found;
    }

    public String weigh(int value) {
        switch (value) {
            case 0:
            case 1:
                return "light";
            case 2:
                return "middling";
            default:
                return "heavy";
        }
    }

    public int scored(Size which) {
        return switch (which) {
            case NONE -> 0;
            case SOME -> 1;
            default -> 2;
        };
    }

    public String guarded(String text) {
        try {
            return text.substring(0, 2);
        } catch (IndexOutOfBoundsException | NullPointerException e) {
            return "";
        } finally {
            taps++;
        }
    }

    public int total(int... values) {
        int sum = 0;
        for (int one : values) {
            sum = sum + one;
        }
        return sum;
    }

    public String tell(Object thing) {
        if (thing instanceof String text) {
            return text;
        }
        return String.valueOf(thing);
    }

    public void later(Runnable which) {
        which.run();
    }

    public void tidy() {
        later(this::reset);
    }

    public Ticker ticker() {
        return new Ticker();
    }

    /// A class that belongs to an instance, reading what it holds.
    public final class Ticker {
        public int next() {
            taps = taps + 1;
            return taps;
        }
    }

    public static final class Point {
        private final int x;
        private final int y;

        public Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    public record Pair(int left, int right) { }

    public enum Size {
        NONE, SOME, MANY;

        public static Size of(int count) {
            if (count == 0) {
                return NONE;
            }
            if (count < 5) {
                return SOME;
            }
            return MANY;
        }
    }

    public interface Watcher {
        void changed(int to);

        default String describeChange(int to) {
            return "now " + to;
        }
    }
}
"#,
        )
        .unwrap();

        let project = super::builder::from_project(root.to_str().unwrap())
            .expect("the whole application must compile");
        let names: Vec<&str> = project
            .code
            .iter()
            .map(|one| one.descriptor.as_str())
            .collect();
        for wanted in [
            "Lcom/tr/yt/MainActivity;",
            "Lcom/tr/yt/MainActivity$Ticker;",
            "Lcom/tr/yt/MainActivity$Point;",
            "Lcom/tr/yt/MainActivity$Pair;",
            "Lcom/tr/yt/MainActivity$Size;",
            "Lcom/tr/yt/MainActivity$Watcher;",
        ] {
            assert!(names.contains(&wanted), "{names:?}");
        }
        // The lambda and the class written where it is used each became one
        // more, numbered after the ones with names.
        assert!(
            names.len() >= 8,
            "a lambda and an anonymous class are classes too: {names:?}"
        );

        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_700_000_000, &mut sink)
            .expect("and must pack and sign");
        assert!(outcome.carries_code);
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let written = directory.join("Whole.apk");
        std::fs::write(&written, &outcome.package).unwrap();

        // apksigner verifies the signature over the whole package.
        if let Some(tool) = find_apksigner() {
            let checked = std::process::Command::new(&tool)
                .args([
                    "verify",
                    "--verbose",
                    "--min-sdk-version",
                    &super::compiler::OLDEST_API.to_string(),
                    written.to_str().unwrap(),
                ])
                .output()
                .unwrap();
            let said = format!(
                "{}{}",
                String::from_utf8_lossy(&checked.stdout),
                String::from_utf8_lossy(&checked.stderr)
            );
            assert!(checked.status.success(), "apksigner refused it:\n{said}");
        }

        // And dexdump verifies the code inside it.
        let read = super::archive::read(&outcome.package, &mut Sink::new()).unwrap();
        let entry = read.entry("classes.dex").expect("there is a classes.dex");
        let dex = read.content(&outcome.package, entry).unwrap();
        if let Some(tool) = find_build_tool("dexdump") {
            let held = directory.join("classes.dex");
            std::fs::write(&held, &dex).unwrap();
            let output = std::process::Command::new(&tool)
                .args(["-d", held.to_str().unwrap()])
                .output()
                .unwrap();
            let said = format!(
                "{}{}",
                String::from_utf8_lossy(&output.stdout),
                String::from_utf8_lossy(&output.stderr)
            );
            assert!(output.status.success(), "dexdump refused it:\n{said}");
            for wanted in [
                "Lcom/tr/yt/MainActivity;",
                "Lcom/tr/yt/MainActivity$Size;",
                "packed-switch",
                "move-exception",
                "invoke-interface",
                "$outer",
            ] {
                assert!(said.contains(wanted), "dexdump printed no {wanted:?}");
            }
        }

        eprintln!(
            "java: a whole application -- {} classes, a {} byte signed package that \
             apksigner and dexdump both accept",
            project.code.len(),
            outcome.package.len()
        );
    }

    #[test]
    fn a_project_is_a_manifest_and_language_folders_and_nothing_else() {
        let directory = temp_directory("omni-scaffold");
        let root = directory.join("MyApp");
        let spec = "package=com.tr.yt;label=My App;abis=arm64-v8a;minSdk=30;targetSdk=36;languages=kotlin,rust,cpp,java";

        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let spec_c = std::ffi::CString::new(spec).unwrap();
        let report = call_ffi(|| unsafe {
            super::ffi::omni_create_project(root_c.as_ptr(), spec_c.as_ptr())
        });
        assert!(is_structurally_valid(&report), "{report}");
        assert!(report.contains("\"created\":true"), "{report}");

        let mut names: Vec<String> = std::fs::read_dir(&root)
            .unwrap()
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.file_name().to_string_lossy().to_string())
            .collect();
        names.sort();
        assert_eq!(
            names,
            vec![
                "AndroidManifest.xml",
                "Java",
                "Kotlin",
                "Native",
                "Res",
                "Rust"
            ],
            "the root holds the manifest, the language folders and the resource folder, \
             and nothing else"
        );

        for (folder, file) in [
            ("Kotlin", "MainActivity.kt"),
            ("Java", "MainActivity.java"),
            ("Native", "Main.cpp"),
            ("Rust", "Lib.rs"),
        ] {
            let inside: Vec<String> = std::fs::read_dir(root.join(folder))
                .unwrap()
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.file_name().to_string_lossy().to_string())
                .collect();
            assert_eq!(
                inside,
                vec![file],
                "{folder} holds one starter file and no subfolder"
            );
        }

        let manifest = std::fs::read_to_string(root.join("AndroidManifest.xml")).unwrap();
        assert!(manifest.contains("package=\"com.tr.yt\""), "{manifest}");
        assert!(
            manifest.contains(&format!(
                "android:label=\"@string/{}\"",
                super::scaffold::LABEL_RESOURCE
            )),
            "{manifest}"
        );
        assert!(
            manifest.contains("android:minSdkVersion=\"30\""),
            "{manifest}"
        );

        let base = root
            .join(super::scaffold::RES_FOLDER)
            .join(super::scaffold::values_folder(super::scaffold::BASE_LOCALE))
            .join(super::scaffold::STRINGS_FILE);
        assert!(
            std::fs::read_to_string(&base).unwrap().contains("My App"),
            "the name the manifest points at is in the folder a device falls back to"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    fn gather_png_files(root: &std::path::Path, into: &mut Vec<std::path::PathBuf>, cap: usize) {
        if into.len() >= cap {
            return;
        }
        let Ok(entries) = std::fs::read_dir(root) else {
            return;
        };
        let mut children: Vec<std::path::PathBuf> =
            entries.flatten().map(|entry| entry.path()).collect();
        children.sort();
        for child in children {
            if into.len() >= cap {
                return;
            }
            if child.is_dir() {
                gather_png_files(&child, into, cap);
            } else if child.extension().and_then(|e| e.to_str()) == Some("png") {
                into.push(child);
            }
        }
    }

    fn python_available() -> bool {
        std::process::Command::new("python3")
            .arg("-c")
            .arg("import zlib")
            .output()
            .map(|out| out.status.success())
            .unwrap_or(false)
    }

    fn python_compress(data: &[u8], level: u32, raw: bool) -> Option<Vec<u8>> {
        let directory = temp_directory("omni-zlib-in");
        let source = directory.join("plain.bin");
        let target = directory.join("packed.bin");
        std::fs::write(&source, data).ok()?;
        let program = format!(
            "import zlib\ndata = open(r'{}', 'rb').read()\nc = zlib.compressobj({}, zlib.DEFLATED, {})\nout = c.compress(data) + c.flush()\nopen(r'{}', 'wb').write(out)\n",
            source.to_str()?,
            level,
            if raw { -15 } else { 15 },
            target.to_str()?,
        );
        let run = std::process::Command::new("python3")
            .arg("-c")
            .arg(&program)
            .output()
            .ok()?;
        if !run.status.success() {
            std::fs::remove_dir_all(&directory).ok();
            return None;
        }
        let packed = std::fs::read(&target).ok();
        std::fs::remove_dir_all(&directory).ok();
        packed
    }

    #[test]
    fn deflate_writes_a_stream_an_independent_reader_accepts() {
        let mut seed = 0x2b7e_1516_28ae_d2a6u64;
        let mut next = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed
        };

        let mut cases: Vec<Vec<u8>> = vec![
            Vec::new(),
            b"a".to_vec(),
            b"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_vec(),
            b"the same words the same words the same words the same words".to_vec(),
            vec![0u8; 200_000],
            (0..=255u8).cycle().take(120_000).collect(),
        ];
        for size in [2usize, 3, 4, 258, 259, 1_024, 40_000] {
            cases.push((0..size).map(|_| (next() & 0xff) as u8).collect());
        }
        let mut lumpy = Vec::new();
        for _ in 0..4_000 {
            let run = (next() % 60) as usize;
            let byte = (next() & 0x0f) as u8;
            lumpy.extend(std::iter::repeat_n(byte, run));
        }
        cases.push(lumpy);

        let mut original = 0usize;
        let mut packed_total = 0usize;
        for case in &cases {
            let packed = super::deflate::zlib(case);
            let read = super::inflate::zlib(&packed).unwrap_or_else(|error| {
                panic!("{} bytes: {} {}", case.len(), error.code, error.message)
            });
            assert_eq!(
                &read,
                case,
                "{} bytes did not survive the round trip",
                case.len()
            );
            original += case.len();
            packed_total += packed.len();
        }

        if python_available() {
            for case in &cases {
                let packed = super::deflate::zlib(case);
                let directory = temp_directory("omni-deflate");
                let source = directory.join("packed.bin");
                std::fs::write(&source, &packed).unwrap();
                let program = format!(
                    "import zlib,sys\nd=open(r'{}','rb').read()\nsys.stdout.write(str(len(zlib.decompress(d))))\n",
                    source.to_str().unwrap()
                );
                let run = std::process::Command::new("python3")
                    .arg("-c")
                    .arg(&program)
                    .output()
                    .unwrap();
                let reported = String::from_utf8_lossy(&run.stdout).to_string();
                assert!(
                    run.status.success(),
                    "an independent reader refused what this build wrote for {} bytes:\n{}",
                    case.len(),
                    String::from_utf8_lossy(&run.stderr)
                );
                assert_eq!(
                    reported,
                    case.len().to_string(),
                    "an independent reader read a different length back"
                );
                std::fs::remove_dir_all(&directory).ok();
            }
        } else {
            assert!(
                std::env::var("OMNI_REQUIRE_INFLATE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_INFLATE_CONFORMANCE is set but no independent reader is here"
            );
        }

        assert!(
            packed_total < original,
            "{packed_total} bytes out of {original} is not compression"
        );
        eprintln!(
            "deflate: {original} bytes written as {packed_total}, read back exactly by this \
             build and by an independent reader"
        );
    }

    #[test]
    fn inflate_reads_what_an_independent_compressor_wrote() {
        if !python_available() {
            assert!(
                std::env::var("OMNI_REQUIRE_INFLATE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_INFLATE_CONFORMANCE is set but no independent compressor is here"
            );
            eprintln!("inflate: no independent compressor is available here");
            return;
        }

        let mut seed = 0x51ed_2701_9fa3_1c5du64;
        let mut next = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            seed
        };

        let mut cases: Vec<Vec<u8>> = vec![
            Vec::new(),
            b"a".to_vec(),
            b"the same words the same words the same words the same words".to_vec(),
            vec![0u8; 70_000],
            (0..=255u8).cycle().take(100_000).collect(),
        ];
        for size in [1usize, 17, 255, 4096, 33_000] {
            cases.push((0..size).map(|_| (next() & 0xff) as u8).collect());
        }
        let mut lumpy = Vec::new();
        for _ in 0..2_000 {
            let run = (next() % 40) as usize;
            let byte = (next() & 0xff) as u8;
            lumpy.extend(std::iter::repeat_n(byte, run));
        }
        cases.push(lumpy);

        let mut checked = 0usize;
        for case in &cases {
            for level in [0u32, 1, 6, 9] {
                let Some(packed) = python_compress(case, level, false) else {
                    continue;
                };
                let read = super::inflate::zlib(&packed).unwrap_or_else(|error| {
                    panic!(
                        "level {level}, {} bytes: {} {}",
                        case.len(),
                        error.code,
                        error.message
                    )
                });
                assert_eq!(&read, case, "level {level}, {} bytes", case.len());

                let Some(raw) = python_compress(case, level, true) else {
                    continue;
                };
                assert_eq!(&super::inflate::raw(&raw).unwrap(), case);
                checked += 2;
            }
        }

        assert!(checked >= 20, "only {checked} streams were checked");
        eprintln!(
            "inflate: {checked} streams written by an independent compressor read back exactly, \
             across stored, fixed and dynamic blocks"
        );
    }

    #[test]
    fn inflate_refuses_a_stream_that_has_been_damaged() {
        if !python_available() {
            eprintln!("inflate: no independent compressor is available here");
            return;
        }
        let plain: Vec<u8> = (0..5_000u32).map(|value| (value % 251) as u8).collect();
        let Some(packed) = python_compress(&plain, 6, false) else {
            return;
        };
        assert_eq!(super::inflate::zlib(&packed).unwrap(), plain);

        let mut wrong_header = packed.clone();
        wrong_header[0] ^= 0x10;
        assert!(super::inflate::zlib(&wrong_header).is_err());

        let mut wrong_check = packed.clone();
        let last = wrong_check.len() - 1;
        wrong_check[last] ^= 0x01;
        assert_eq!(
            super::inflate::zlib(&wrong_check).unwrap_err().code,
            "EI106"
        );

        let truncated = &packed[..packed.len() - 8];
        assert!(super::inflate::zlib(truncated).is_err());

        assert!(super::inflate::zlib(&[]).is_err());
        assert_eq!(
            super::inflate::zlib(&[0x78, 0x9c, 0, 0, 0, 0])
                .unwrap_err()
                .code,
            "EI101",
            "a header with no deflate payload behind it ends before its data"
        );
        assert_eq!(
            super::inflate::zlib(&[0x78, 0x9c, 0x06, 0, 0, 0, 0])
                .unwrap_err()
                .code,
            "EI135",
            "block type three is the one the format reserves"
        );
    }

    #[test]
    fn the_image_reader_accepts_every_real_png_it_is_shown() {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            std::env::var("ANDROID_SDK_ROOT").ok(),
            Some("/usr/share/icons".to_string()),
            Some("/usr/share/pixmaps".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                roots.push(path);
            }
        }

        let mut files = Vec::new();
        for root in &roots {
            gather_png_files(root, &mut files, 200);
        }

        if files.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_IMAGE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_IMAGE_CONFORMANCE is set but no PNG files were found, so the \
                 image reader was never shown one written by another tool"
            );
            eprintln!("image conformance: no PNG files are available here");
            return;
        }

        let mut read = 0usize;
        let mut oversized = 0usize;
        for file in &files {
            let bytes = std::fs::read(file).unwrap();
            match super::image::read_png(&bytes) {
                Ok(png) => {
                    let width = u32::from_be_bytes([bytes[16], bytes[17], bytes[18], bytes[19]]);
                    let height = u32::from_be_bytes([bytes[20], bytes[21], bytes[22], bytes[23]]);
                    assert_eq!(png.width, width, "{}", file.display());
                    assert_eq!(png.height, height, "{}", file.display());
                    assert_eq!(png.bit_depth, bytes[24], "{}", file.display());
                    assert_eq!(png.bytes, bytes.len(), "{}", file.display());
                    assert!(png.chunks >= 3, "{}", file.display());
                    read += 1;
                }
                Err(error) if error.code == "EM015" => oversized += 1,
                Err(error) => panic!(
                    "the reader refused a real PNG: {} {} {}\n{:?}",
                    file.display(),
                    error.code,
                    error.message,
                    error.context
                ),
            }
        }

        assert!(read > 0, "no PNG was read");
        eprintln!(
            "image conformance: {read} PNG files written by other tools read here, \
             {oversized} refused only for being larger than an icon"
        );
    }

    #[test]
    fn every_real_png_decodes_and_what_this_build_writes_reads_back() {
        let mut roots: Vec<std::path::PathBuf> = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                roots.push(path);
            }
        }
        let mut files = Vec::new();
        for root in &roots {
            gather_png_files(root, &mut files, 200);
        }
        if files.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_IMAGE_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_IMAGE_CONFORMANCE is set but no PNG files were found"
            );
            eprintln!("codec: no PNG files are available here");
            return;
        }

        let mut decoded = 0usize;
        let mut interlaced = 0usize;
        let mut source_bytes = 0usize;
        let mut written_bytes = 0usize;

        for file in &files {
            let bytes = std::fs::read(file).unwrap();
            let raster = match super::image::decode(&bytes) {
                Ok(raster) => raster,
                Err(error) if error.code == "EM032" => {
                    interlaced += 1;
                    continue;
                }
                Err(error) if error.code == "EM015" => continue,
                Err(error) => panic!(
                    "the codec refused a real PNG: {} {} {}\n{:?}",
                    file.display(),
                    error.code,
                    error.message,
                    error.context
                ),
            };

            let header = super::image::read_png(&bytes).unwrap();
            assert_eq!(raster.width, header.width, "{}", file.display());
            assert_eq!(raster.height, header.height, "{}", file.display());
            assert_eq!(
                raster.pixels.len(),
                raster.width as usize * raster.height as usize * 4
            );

            let written = super::image::encode(&raster).unwrap();
            super::image::read_png(&written).unwrap_or_else(|error| {
                panic!(
                    "this build wrote a PNG it will not read: {} {}",
                    error.code, error.message
                )
            });
            let again = super::image::decode(&written).unwrap();
            assert_eq!(again.width, raster.width);
            assert_eq!(again.height, raster.height);
            assert_eq!(
                again.pixels,
                raster.pixels,
                "{} did not survive a write and a read",
                file.display()
            );

            decoded += 1;
            source_bytes += bytes.len();
            written_bytes += written.len();
        }

        assert!(decoded > 0, "no PNG was decoded");
        assert!(
            written_bytes * 10 < source_bytes * 11,
            "this build wrote {written_bytes} bytes where the tools that made these images wrote \
             {source_bytes}. Within a tenth is the bar an encoder that picks its own colour type, \
             palette, filter and Huffman tables should clear; further from it means one of those \
             stopped working."
        );
        eprintln!(
            "codec: {decoded} images written by other tools decoded to pixels, written again by \
             this build and read back identical ({source_bytes} bytes in, {written_bytes} out, \
             {interlaced} interlaced refused)"
        );
    }

    #[test]
    fn the_pixels_of_a_known_image_are_the_ones_an_independent_reader_sees() {
        if !python_available() {
            eprintln!("codec: no independent reader is available here");
            return;
        }

        let directory = temp_directory("omni-codec");
        let source = directory.join("made.png");
        let dump = directory.join("pixels.txt");
        let program = format!(
            "import zlib,struct\n\
             w,h=7,5\n\
             rows=b''\n\
             for y in range(h):\n\
             \x20   rows+=b'\\x00'\n\
             \x20   for x in range(w):\n\
             \x20       rows+=bytes([(x*31)%256,(y*57)%256,(x*y*13)%256,(255-(x*9))%256])\n\
             def chunk(k,b):\n\
             \x20   return struct.pack('>I',len(b))+k+b+struct.pack('>I',zlib.crc32(k+b)&0xffffffff)\n\
             png=b'\\x89PNG\\r\\n\\x1a\\n'\n\
             png+=chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))\n\
             png+=chunk(b'IDAT',zlib.compress(rows,9))\n\
             png+=chunk(b'IEND',b'')\n\
             open(r'{}','wb').write(png)\n\
             open(r'{}','w').write(','.join(str(v) for v in rows if True))\n",
            source.to_str().unwrap(),
            dump.to_str().unwrap(),
        );
        let made = std::process::Command::new("python3")
            .arg("-c")
            .arg(&program)
            .output()
            .unwrap();
        assert!(
            made.status.success(),
            "{}",
            String::from_utf8_lossy(&made.stderr)
        );

        let bytes = std::fs::read(&source).unwrap();
        let raster = super::image::decode(&bytes).expect("a PNG another tool wrote must decode");
        assert_eq!(raster.width, 7);
        assert_eq!(raster.height, 5);
        for y in 0..5u32 {
            for x in 0..7u32 {
                assert_eq!(
                    raster.at(x, y),
                    [
                        ((x * 31) % 256) as u8,
                        ((y * 57) % 256) as u8,
                        ((x * y * 13) % 256) as u8,
                        ((255 - (x * 9)) % 256) as u8,
                    ],
                    "pixel {x},{y}"
                );
            }
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("codec: every pixel of a known image matches what it was written with");
    }

    #[test]
    fn a_launcher_set_is_every_size_android_asks_for_in_both_shapes() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 12);
            }
        }
        let Some(source) = files.into_iter().find(|file| {
            std::fs::read(file)
                .ok()
                .and_then(|bytes| super::image::decode(&bytes).ok())
                .map(|raster| raster.width >= 24 && raster.height >= 24)
                .unwrap_or(false)
        }) else {
            eprintln!("launcher: no usable PNG is available here");
            return;
        };

        let bytes = std::fs::read(&source).unwrap();
        let set = super::image::launcher_set(&bytes).expect("a launcher set must be produced");
        assert_eq!(set.len(), super::image::LAUNCHER_SIZES.len() * 2);

        for made in &set {
            let header = super::image::read_png(&made.bytes)
                .unwrap_or_else(|error| panic!("{} {}", error.code, error.message));
            assert_eq!(header.width, made.edge, "{} {}", made.folder, made.name);
            assert_eq!(header.height, made.edge);
            assert!(!header.interlaced);

            // Written as small as it goes, an icon may come out indexed, and an
            // indexed image carries its transparency in tRNS rather than in a
            // channel of its own. Android reads either. What has to hold is that
            // the picture reads back at the size it claims, with its alpha
            // intact — which the corners below prove for every size.
            let back = super::image::decode(&made.bytes)
                .expect("a launcher icon this build wrote must read back");
            assert_eq!(back.width, made.edge, "{} {}", made.folder, made.name);
            assert_eq!(back.height, made.edge);
        }

        for (folder, edge) in super::image::LAUNCHER_SIZES {
            let square = set
                .iter()
                .find(|made| made.folder == *folder && made.name == "ic_launcher")
                .unwrap();
            let round = set
                .iter()
                .find(|made| made.folder == *folder && made.name == "ic_launcher_round")
                .unwrap();
            let square_pixels = super::image::decode(&square.bytes).unwrap();
            let round_pixels = super::image::decode(&round.bytes).unwrap();

            assert_eq!(
                square_pixels.at(edge / 2, edge / 2),
                round_pixels.at(edge / 2, edge / 2),
                "the centre of the round icon is the centre of the square one"
            );
            assert_eq!(
                round_pixels.at(0, 0)[3],
                0,
                "a corner of the round icon at {edge} is outside the circle and must be clear"
            );
            assert_eq!(
                round_pixels.at(edge - 1, edge - 1)[3],
                0,
                "the opposite corner at {edge} must be clear too"
            );
        }

        let total: usize = set.iter().map(|made| made.bytes.len()).sum();
        eprintln!(
            "launcher: {} images from one source, {} to {} pixels, square and round, {total} bytes",
            set.len(),
            super::image::LAUNCHER_SIZES[0].1,
            super::image::LAUNCHER_SIZES[super::image::LAUNCHER_SIZES.len() - 1].1,
        );
    }

    #[test]
    fn the_image_reader_refuses_a_png_that_has_been_damaged() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 4);
            }
        }
        let Some(file) = files.into_iter().find(|file| {
            std::fs::read(file)
                .ok()
                .is_some_and(|bytes| super::image::read_png(&bytes).is_ok())
        }) else {
            eprintln!("image conformance: no PNG file is available here");
            return;
        };
        let sound = std::fs::read(&file).unwrap();
        super::image::read_png(&sound).expect("the file must read before it is damaged");

        let mut wrong_signature = sound.clone();
        wrong_signature[1] = b'Q';
        assert_eq!(
            super::image::read_png(&wrong_signature).unwrap_err().code,
            "EM002"
        );

        let mut flipped = sound.clone();
        flipped[20] ^= 0x01;
        assert_eq!(super::image::read_png(&flipped).unwrap_err().code, "EM006");

        let truncated = &sound[..sound.len() - 1];
        let refused = super::image::read_png(truncated).unwrap_err();
        assert!(
            refused.code == "EM005" || refused.code == "EM003" || refused.code == "EM006",
            "{} {}",
            refused.code,
            refused.message
        );

        let mut trailing = sound.clone();
        trailing.push(0);
        assert_eq!(super::image::read_png(&trailing).unwrap_err().code, "EM018");

        assert_eq!(super::image::read_png(&[]).unwrap_err().code, "EM002");
        assert_eq!(
            super::image::read_png(&super::image::SIGNATURE)
                .unwrap_err()
                .code,
            "EM016"
        );
    }

    #[test]
    fn the_editor_reads_writes_and_stays_inside_the_project() {
        let directory = temp_directory("omni-workspace");
        let root = directory.join("Edited");
        let text = root.to_str().unwrap().to_string();
        super::scaffold::create(&text, &super::scaffold::Spec::default()).unwrap();

        let listed = super::workspace::list_projects(directory.to_str().unwrap());
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].package, super::scaffold::DEFAULT_PACKAGE);
        assert_eq!(
            listed[0].label, "My App",
            "the manifest points at a string resource, and the listing resolves it"
        );
        assert_eq!(listed[0].version_name, "1.0.0");
        assert_eq!(listed[0].version_code, 1);
        assert_eq!(listed[0].min_sdk, 30);
        assert_eq!(listed[0].target_sdk, 36);
        assert!(listed[0].icon.is_none());

        let entries = super::workspace::tree(&text).unwrap();
        assert!(entries
            .iter()
            .any(|entry| entry.path == "AndroidManifest.xml"));
        assert!(entries
            .iter()
            .any(|entry| entry.path == "Kotlin" && entry.folder));

        let manifest = super::workspace::read_text(&text, "AndroidManifest.xml").unwrap();
        assert!(
            manifest.contains(super::scaffold::DEFAULT_PACKAGE),
            "{manifest}"
        );

        super::workspace::create_folder(&text, "Kotlin/com/tr/yt").unwrap();
        super::workspace::write_text(&text, "Kotlin/com/tr/yt/Screen.kt", "class Screen\n")
            .unwrap();
        assert_eq!(
            super::workspace::read_text(&text, "Kotlin/com/tr/yt/Screen.kt").unwrap(),
            "class Screen\n"
        );

        for escape in [
            "../outside.txt",
            "/etc/passwd",
            "Kotlin/../../outside.txt",
            "Kotlin/./../../outside.txt",
            "",
        ] {
            let refused = super::workspace::write_text(&text, escape, "no")
                .expect_err("a path that leaves the project must be refused");
            assert_eq!(refused.code, "EW100", "{escape}: {}", refused.message);
        }
        assert!(!directory.join("outside.txt").exists());
        assert!(!std::path::Path::new("/etc/passwd")
            .metadata()
            .map(|data| data.len() == 2)
            .unwrap_or(false));

        std::fs::write(root.join("Kotlin/Binary.bin"), [0xff, 0xfe, 0x00, 0x01]).unwrap();
        assert_eq!(
            super::workspace::read_text(&text, "Kotlin/Binary.bin")
                .unwrap_err()
                .code,
            "EW113"
        );

        let bin = directory.join("Trash").to_str().unwrap().to_string();
        let now = 1_787_000_000;
        assert_eq!(
            super::workspace::remove(&text, "AndroidManifest.xml", &bin, now)
                .unwrap_err()
                .code,
            "EW140"
        );
        let thrown = super::workspace::remove(&text, "Kotlin/Binary.bin", &bin, now).unwrap();
        assert!(!root.join("Kotlin/Binary.bin").exists());
        assert_eq!(thrown.name, "Binary.bin");
        assert_eq!(thrown.bytes, 4);

        super::workspace::rename(&text, "Kotlin/MainActivity.kt", "Kotlin/Screen.kt").unwrap();
        assert!(!root.join("Kotlin/MainActivity.kt").exists());
        assert!(root.join("Kotlin/Screen.kt").is_file());
        assert_eq!(
            super::workspace::rename(&text, "Kotlin/Screen.kt", "AndroidManifest.xml")
                .unwrap_err()
                .code,
            "EW150"
        );
        assert_eq!(
            super::workspace::rename(&text, "Kotlin", "Kotlin/Inside")
                .unwrap_err()
                .code,
            "EW153"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn what_is_deleted_waits_a_day_in_the_trash_and_can_be_put_back() {
        let directory = temp_directory("omni-trash");
        let root = directory.join("Held");
        let text = root.to_str().unwrap().to_string();
        super::scaffold::create(&text, &super::scaffold::Spec::default()).unwrap();
        let bin = directory
            .join(super::trash::FOLDER)
            .to_str()
            .unwrap()
            .to_string();
        let now = 1_787_000_000;

        super::workspace::write_text(&text, "Kotlin/Gone.kt", "class Gone\n").unwrap();
        let thrown = super::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        assert!(!root.join("Kotlin/Gone.kt").exists(), "it left the project");
        assert_eq!(
            thrown.expires_at - thrown.deleted_at,
            super::trash::HELD_SECONDS,
            "it is held for a day"
        );

        let held = super::trash::list(&bin, now);
        assert_eq!(held.len(), 1);
        assert_eq!(held[0].name, "Gone.kt");
        assert_eq!(held[0].seconds_left(now), super::trash::HELD_SECONDS);

        super::trash::restore(&bin, &thrown.id, now).unwrap();
        assert_eq!(
            super::workspace::read_text(&text, "Kotlin/Gone.kt").unwrap(),
            "class Gone\n",
            "what came back is what went in"
        );
        assert!(super::trash::list(&bin, now).is_empty());

        let again = super::workspace::remove(&text, "Kotlin/Gone.kt", &bin, now).unwrap();
        super::workspace::write_text(&text, "Kotlin/Gone.kt", "written since\n").unwrap();
        assert_eq!(
            super::trash::restore(&bin, &again.id, now)
                .unwrap_err()
                .code,
            "ET012",
            "restoring never writes over what is there now"
        );

        let a_day_later = now + super::trash::HELD_SECONDS;
        assert!(
            super::trash::list(&bin, a_day_later).is_empty(),
            "a day on, the trash no longer offers it"
        );
        assert_eq!(
            super::trash::restore(&bin, &again.id, a_day_later)
                .unwrap_err()
                .code,
            "ET011"
        );
        assert_eq!(super::trash::sweep(&bin, a_day_later), 1);
        assert!(!std::path::Path::new(&bin).join(&again.id).exists());

        let folder = super::workspace::remove(&text, "Kotlin", &bin, now).unwrap();
        assert!(folder.folder, "a folder goes to the trash whole");
        assert!(!root.join("Kotlin").exists());
        super::trash::restore(&bin, &folder.id, now).unwrap();
        assert!(root.join("Kotlin").is_dir());

        super::workspace::remove(&text, "Kotlin", &bin, now).unwrap();
        assert_eq!(super::trash::empty(&bin), 1);
        assert!(super::trash::list(&bin, now).is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_project_keeps_the_image_the_developer_chose() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| super::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("project image: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-icon");
        let root = directory.join("Pictured");
        let text = root.to_str().unwrap().to_string();
        super::scaffold::create(&text, &super::scaffold::Spec::default()).unwrap();

        let stored = super::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();
        assert!(stored.width > 0 && stored.height > 0);
        assert_eq!(
            std::fs::read(&source).unwrap(),
            std::fs::read(super::scaffold::icon_path(&text)).unwrap()
        );
        let read_back = super::scaffold::read_icon(&text).expect("the stored image must read");
        assert_eq!(read_back.width, stored.width);
        assert_eq!(read_back.height, stored.height);
        assert!(super::workspace::describe(&text).unwrap().icon.is_some());

        let not_an_image = root.join("AndroidManifest.xml");
        assert_eq!(
            super::scaffold::set_icon(&text, not_an_image.to_str().unwrap())
                .unwrap_err()
                .code,
            "EM002"
        );

        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let project = super::builder::from_project(&text).unwrap();
        let outcome = super::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();
        let archive = archive::read(&outcome.package, &mut sink).unwrap();
        assert!(
            !archive
                .entries()
                .iter()
                .any(|entry| entry.name.contains("Icon.png")),
            "the image is stored with the project, and this build does not claim it reached \
             the package"
        );

        std::fs::remove_dir_all(&directory).ok();
    }

    fn find_bundletool() -> Option<Vec<String>> {
        if let Ok(command) = std::env::var("OMNI_BUNDLETOOL") {
            let parts: Vec<String> = command
                .split_whitespace()
                .map(|part| part.to_string())
                .collect();
            if !parts.is_empty() {
                return Some(parts);
            }
        }

        let home = std::env::var("HOME").unwrap_or_else(|_| "/root".to_string());
        let cache = std::path::PathBuf::from(&home).join(".gradle/caches/modules-2/files-2.1");
        if !cache.join("com.android.tools.build/bundletool").is_dir() {
            return None;
        }

        let mut jars = Vec::new();
        collect_jars(&cache, &mut jars, 0);
        if jars.is_empty() {
            return None;
        }
        jars.sort();
        Some(vec![
            "java".to_string(),
            "-cp".to_string(),
            jars.join(":"),
            "com.android.tools.build.bundletool.BundleToolMain".to_string(),
        ])
    }

    fn collect_jars(root: &std::path::Path, into: &mut Vec<String>, depth: usize) {
        if depth > 8 || into.len() > 4_000 {
            return;
        }
        let Ok(entries) = std::fs::read_dir(root) else {
            return;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                collect_jars(&path, into, depth + 1);
            } else if path.extension().and_then(|e| e.to_str()) == Some("jar") {
                let Some(text) = path.to_str() else { continue };
                if text.contains("-sources") || text.contains("-javadoc") {
                    continue;
                }
                into.push(text.to_string());
            }
        }
    }

    #[test]
    fn the_bundle_writer_produces_a_bundle_bundletool_accepts() {
        let Some(bundletool) = find_bundletool() else {
            assert!(
                std::env::var("OMNI_REQUIRE_BUNDLETOOL").is_err(),
                "OMNI_REQUIRE_BUNDLETOOL is set but bundletool was not found, so the bundle \
                 this build writes was never handed to the tool that judges one"
            );
            eprintln!("bundle conformance: bundletool is not available here");
            return;
        };
        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_BUNDLETOOL").is_err(),
                "OMNI_REQUIRE_BUNDLETOOL is set but aapt2 is missing, and bundletool needs it"
            );
            eprintln!("bundle conformance: aapt2 is not available here");
            return;
        };

        let spec = super::scaffold::Spec {
            package: "com.tr.yt".to_string(),
            label: "Bundled".to_string(),
            version_name: "1.0.0".to_string(),
            version_code: 3,
            ..super::scaffold::Spec::default()
        };
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let picture = files
            .into_iter()
            .find(|file| super::image::read_png_file(file.to_str().unwrap_or_default()).is_ok());

        let mut project = super::builder::from_spec(&spec).unwrap();
        project.icon = picture.as_ref().map(|path| std::fs::read(path).unwrap());
        project.files = vec![
            (
                "lib/arm64-v8a/libomni_core.so".to_string(),
                b"\x7fELF not a real object, only a path to place".to_vec(),
            ),
            (
                "notes.txt".to_string(),
                b"carried at the package root".to_vec(),
            ),
        ];
        let outcome = super::bundle::write(&project).expect("a compliant project must bundle");
        assert!(outcome.carries_code);
        assert_eq!(outcome.carries_image, project.icon.is_some());
        let images = super::image::LAUNCHER_SIZES.len() * 2;
        assert_eq!(
            outcome.entries,
            if outcome.carries_image { 6 + images } else { 5 },
            "config, manifest, dex, a native library, a root file, and when there is an image \
             the resource table and {images} launcher images"
        );

        let directory = temp_directory("omni-bundle");
        let path = directory.join("omni.aab");
        std::fs::write(&path, &outcome.bundle).unwrap();

        let store = directory.join("bundle.jks");
        let keytool = std::process::Command::new("keytool")
            .args([
                "-genkeypair",
                "-keystore",
                store.to_str().unwrap(),
                "-storepass",
                "password",
                "-keypass",
                "password",
                "-alias",
                "omni",
                "-keyalg",
                "RSA",
                "-keysize",
                "2048",
                "-validity",
                "3650",
                "-dname",
                "CN=Omni",
            ])
            .output()
            .expect("keytool must run");
        assert!(
            keytool.status.success(),
            "{}",
            String::from_utf8_lossy(&keytool.stderr)
        );

        let apks = directory.join("omni.apks");
        let mut command = std::process::Command::new(&bundletool[0]);
        command.args(&bundletool[1..]);
        command.args([
            "build-apks",
            &format!("--bundle={}", path.to_str().unwrap()),
            &format!("--output={}", apks.to_str().unwrap()),
            "--mode=universal",
            &format!("--aapt2={}", aapt2.to_str().unwrap()),
            &format!("--ks={}", store.to_str().unwrap()),
            "--ks-pass=pass:password",
            "--ks-key-alias=omni",
            "--key-pass=pass:password",
            "--overwrite",
        ]);
        let built = command.output().expect("bundletool must run");
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&built.stdout),
            String::from_utf8_lossy(&built.stderr)
        );
        assert!(built.status.success(), "bundletool refused it:\n{report}");

        let unpacked = directory.join("apks");
        std::fs::create_dir_all(&unpacked).unwrap();
        let unzipped = std::process::Command::new("unzip")
            .args([
                "-o",
                "-q",
                apks.to_str().unwrap(),
                "-d",
                unpacked.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(unzipped.status.success());

        let universal = unpacked.join("universal.apk");
        assert!(universal.is_file(), "bundletool produced no universal APK");

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                universal.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let tree = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(dumped.status.success(), "{tree}");

        for expected in [
            "A: package=\"com.tr.yt\"",
            "android:versionCode(0x0101021b)=3",
            "android:versionName(0x0101021c)=\"1.0.0\"",
            "android:minSdkVersion(0x0101020c)=30",
            "android:targetSdkVersion(0x01010270)=36",
            "android:label(0x01010001)=@0x7f020000",
            "android:allowBackup(0x01010280)=false",
            "android:extractNativeLibs(0x010104ea)=false",
            "E: activity",
            "android:name(0x01010003)=\"com.tr.yt.MainActivity\"",
            "android:exported(0x01010010)=true",
            "android.intent.action.MAIN",
            "android.intent.category.LAUNCHER",
        ] {
            assert!(tree.contains(expected), "missing {expected:?} in\n{tree}");
        }

        let extracted = std::process::Command::new("unzip")
            .args(["-p", universal.to_str().unwrap(), "classes.dex"])
            .output()
            .unwrap();
        assert!(extracted.status.success());
        let classes = dex::read(&extracted.stdout, &mut Sink::new()).expect("our dex must read");
        assert_eq!(classes.class_names(), vec!["com.tr.yt.MainActivity"]);

        let listed = std::process::Command::new("unzip")
            .args(["-l", universal.to_str().unwrap()])
            .output()
            .unwrap();
        let names = String::from_utf8_lossy(&listed.stdout).to_string();
        assert!(names.contains("lib/arm64-v8a/libomni_core.so"), "{names}");
        assert!(names.contains("notes.txt"), "{names}");

        if outcome.carries_image {
            assert!(names.contains("resources.arsc"), "{names}");
            let badging = std::process::Command::new(&aapt2)
                .args(["dump", "badging", universal.to_str().unwrap()])
                .output()
                .unwrap();
            let reported = String::from_utf8_lossy(&badging.stdout).to_string();
            assert!(badging.status.success(), "{reported}");
            assert!(
                reported.contains("ic_launcher"),
                "bundletool must carry the icon through into the package it builds:\n{reported}"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "bundle conformance: {} bytes handed to bundletool, which built and signed a \
             universal APK aapt2 reads back attribute for attribute",
            outcome.bundle.len()
        );
    }

    #[test]
    fn the_bundle_writer_refuses_what_it_cannot_write_faithfully() {
        let mut sink = Sink::new();
        let referenced = super::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\">",
                "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
                "<application android:label=\"@string/name\" android:allowBackup=\"false\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();
        assert_eq!(
            super::bundle::encode_manifest(&referenced)
                .expect_err("a name this build cannot resolve must be refused")
                .code,
            "EN011"
        );

        let unknown = super::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\">",
                "<application android:notAnAttributeAndroidHas=\"1\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();
        assert_eq!(
            super::bundle::encode_manifest(&unknown)
                .expect_err("an attribute with no identifier must be refused")
                .code,
            "EN010"
        );

        let wrong_root = super::xml::parse("<application />", "x.xml", &mut sink).unwrap();
        assert_eq!(
            super::bundle::encode_manifest(&wrong_root)
                .unwrap_err()
                .code,
            "EN001"
        );

        let weak = super::builder::from_manifest(concat!(
            "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
            "package=\"com.tr.yt\" android:versionCode=\"1\" android:versionName=\"1.0.0\">",
            "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
            "<application android:label=\"X\" android:allowBackup=\"false\" ",
            "android:debuggable=\"true\">",
            "<activity android:name=\"com.tr.yt.MainActivity\" android:exported=\"false\" />",
            "</application></manifest>",
        ))
        .unwrap();
        let refused = super::bundle::write(&weak)
            .expect_err("the security policy governs a bundle exactly as it governs a package");
        assert_eq!(refused.code, "EN003");
        assert!(
            refused.context.iter().any(|line| line.starts_with("EG001")),
            "a refusal must name what is wrong: {:?}",
            refused.context
        );
    }

    #[test]
    fn protobuf_varints_are_written_the_way_the_wire_format_defines_them() {
        use super::protobuf::{tag, varint};
        assert_eq!(varint(0), vec![0x00]);
        assert_eq!(varint(1), vec![0x01]);
        assert_eq!(varint(127), vec![0x7f]);
        assert_eq!(varint(128), vec![0x80, 0x01]);
        assert_eq!(varint(300), vec![0xac, 0x02]);
        assert_eq!(varint(16_843_291), vec![0x9b, 0x84, 0x84, 0x08]);
        assert_eq!(
            varint(u64::MAX),
            vec![0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0x01]
        );

        assert_eq!(tag(1, 2), vec![0x0a]);
        assert_eq!(tag(3, 2), vec![0x1a]);
        assert_eq!(tag(5, 0), vec![0x28]);
        assert_eq!(tag(16, 2), vec![0x82, 0x01]);

        let mut message = super::protobuf::Message::new();
        message.text(1, "testing");
        assert_eq!(
            message.as_bytes(),
            &[0x0a, 0x07, b't', b'e', b's', b't', b'i', b'n', b'g']
        );

        let mut outer = super::protobuf::Message::new();
        outer.message(2, &message);
        assert_eq!(
            outer.as_bytes(),
            &[0x12, 0x09, 0x0a, 0x07, b't', b'e', b's', b't', b'i', b'n', b'g']
        );
    }

    #[test]
    fn dimensions_are_written_in_the_fixed_point_the_format_defines() {
        use super::arsc::encode_dimension;
        use super::resources::Unit;

        assert_eq!(encode_dimension(1_000, Unit::Dp).unwrap(), 0x0000_0101);
        assert_eq!(encode_dimension(4_000, Unit::Dp).unwrap(), 0x0000_0401);
        assert_eq!(encode_dimension(12_000, Unit::Dp).unwrap(), 0x0000_0c01);
        assert_eq!(encode_dimension(16_000, Unit::Dp).unwrap(), 0x0000_1001);
        assert_eq!(encode_dimension(14_000, Unit::Sp).unwrap(), 0x0000_0e02);
        assert_eq!(encode_dimension(16_000, Unit::Sp).unwrap(), 0x0000_1002);
        assert_eq!(encode_dimension(0, Unit::Px).unwrap(), 0x0000_0000);

        let half = encode_dimension(1_500, Unit::Dp).unwrap();
        assert_eq!(half & 0xf0, 0x10, "1.5dp needs the 16p7 radix");
        assert_eq!(half & 0x0f, 0x01);
        assert_eq!(half >> 8, 192, "1.5 at 16p7 is 192");

        assert_eq!(
            encode_dimension(40_000_000_000, Unit::Dp)
                .expect_err("a dimension larger than the mantissa must be refused")
                .code,
            "EZ001"
        );
    }

    fn table_for_test() -> super::resources::Compiled {
        let mut sink = Sink::new();
        let mut table = super::resources::Table::for_package(0x7f);
        assert!(table.read_values(
            concat!(
                "<resources>",
                "<string name=\"app_name\">Omni Made</string>",
                "<string name=\"greeting\">Hello</string>",
                "<color name=\"accent\">#ff6cb6ff</color>",
                "<dimen name=\"gap\">12dp</dimen>",
                "<bool name=\"ready\">true</bool>",
                "<integer name=\"tries\">3</integer>",
                "</resources>",
            ),
            "values/values.xml",
            &mut sink,
        ));
        assert!(table.read_file(
            "mipmap",
            "ic_launcher.png",
            "res/mipmap/ic_launcher.png",
            &mut sink
        ));
        assert!(table.read_file(
            "mipmap-xxhdpi",
            "ic_launcher.png",
            "res/mipmap-xxhdpi/ic_launcher.png",
            &mut sink,
        ));
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        table.compile(&mut sink).expect("the table must compile")
    }

    #[test]
    fn the_resource_table_this_build_writes_is_the_one_aapt2_reads() {
        let compiled = table_for_test();
        let table = super::arsc::write("com.tr.yt", &compiled).expect("the table must be written");

        assert_eq!(&table[..2], &super::arsc::RES_TABLE.to_le_bytes());
        assert_eq!(
            u32::from_le_bytes([table[4], table[5], table[6], table[7]]) as usize,
            table.len(),
            "the table header must state the whole size"
        );

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing, so the resource \
                 table this build wrote was never read by anything but itself"
            );
            eprintln!("resource table: aapt2 is not available here");
            return;
        };

        let mut sink = Sink::new();
        let root = super::xml::parse(
            concat!(
                "<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" ",
                "package=\"com.tr.yt\" android:versionCode=\"1\" android:versionName=\"1.0.0\">",
                "<uses-sdk android:minSdkVersion=\"30\" android:targetSdkVersion=\"36\" />",
                "<application android:label=\"X\" android:allowBackup=\"false\" />",
                "</manifest>",
            ),
            "AndroidManifest.xml",
            &mut sink,
        )
        .unwrap();

        let mut builder = ArchiveBuilder::for_android();
        builder
            .add("AndroidManifest.xml", super::axml::encode(&root).unwrap())
            .unwrap();
        builder.add("resources.arsc", table.clone()).unwrap();
        builder
            .add("res/mipmap/ic_launcher.png", b"not a real image".to_vec())
            .unwrap();
        builder
            .add("res/mipmap-xxhdpi/ic_launcher.png", b"nor is this".to_vec())
            .unwrap();
        let apk = builder.finish().unwrap();

        let directory = temp_directory("omni-arsc");
        let path = directory.join("table.apk");
        std::fs::write(&path, &apk).unwrap();

        let dumped = std::process::Command::new(&aapt2)
            .args(["dump", "resources", path.to_str().unwrap()])
            .output()
            .unwrap();
        let text = format!(
            "{}{}",
            String::from_utf8_lossy(&dumped.stdout),
            String::from_utf8_lossy(&dumped.stderr)
        );
        assert!(
            dumped.status.success(),
            "aapt2 refused the table this build wrote:\n{text}"
        );

        for expected in [
            "Package name=com.tr.yt id=7f",
            "type bool id=01",
            "type color id=02",
            "type dimen id=03",
            "type integer id=04",
            "type mipmap id=05",
            "type string id=06",
            "resource 0x7f010000 bool/ready",
            "resource 0x7f020000 color/accent",
            "resource 0x7f030000 dimen/gap",
            "resource 0x7f040000 integer/tries",
            "resource 0x7f050000 mipmap/ic_launcher",
            "resource 0x7f060000 string/app_name",
            "resource 0x7f060001 string/greeting",
            "Omni Made",
            "Hello",
            "res/mipmap/ic_launcher.png",
            "res/mipmap-xxhdpi/ic_launcher.png",
        ] {
            assert!(text.contains(expected), "missing {expected:?} in\n{text}");
        }

        let badging = std::process::Command::new(&aapt2)
            .args(["dump", "badging", path.to_str().unwrap()])
            .output()
            .unwrap();
        assert!(
            badging.status.success(),
            "{}",
            String::from_utf8_lossy(&badging.stderr)
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "resource table: {} bytes, {} identifiers, aapt2 read every one of them back",
            table.len(),
            compiled.assignments().len()
        );
    }

    #[test]
    fn the_name_a_project_carries_is_translated_in_every_language_it_chose() {
        let directory = temp_directory("omni-locales");
        let root = directory.join("Spoken");
        let text = root.to_str().unwrap().to_string();
        let spec = super::scaffold::Spec {
            package: "com.my.app".to_string(),
            label: "Spoken".to_string(),
            locales: vec![
                super::scaffold::BASE_LOCALE.to_string(),
                "tr".to_string(),
                "de".to_string(),
            ],
            ..super::scaffold::Spec::default()
        };
        super::scaffold::create(&text, &spec).unwrap();

        let translations = [("tr", "Konuşulan"), ("de", "Gesprochen")];
        for (locale, translated) in translations {
            super::workspace::write_text(
                &text,
                &format!(
                    "{}/{}/{}",
                    super::scaffold::RES_FOLDER,
                    super::scaffold::values_folder(locale),
                    super::scaffold::STRINGS_FILE
                ),
                &super::scaffold::strings_file(translated),
            )
            .unwrap();
        }

        let project = super::builder::from_project(&text).unwrap();
        assert_eq!(
            project.values.len(),
            3,
            "the base folder and one per translation are read back"
        );

        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect("a translated project must build");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing"
            );
            eprintln!("locales: aapt2 is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };

        let package = directory.join("spoken.apk");
        std::fs::write(&package, &outcome.package).unwrap();
        let dumped = std::process::Command::new(&aapt2)
            .args(["dump", "resources", package.to_str().unwrap()])
            .output()
            .unwrap();
        let listing = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(dumped.status.success(), "{listing}");

        assert!(
            listing.contains("string/app_name"),
            "the name is a string resource in the table aapt2 read\n{listing}"
        );
        assert!(
            listing.contains("\"Spoken\""),
            "the folder a device falls back to carries the untranslated name\n{listing}"
        );
        for (locale, translated) in translations {
            assert!(
                listing.contains(&format!("({locale})")),
                "aapt2 must report a {locale} configuration\n{listing}"
            );
            assert!(
                listing.contains(&format!("\"{translated}\"")),
                "aapt2 must report {translated:?}\n{listing}"
            );
        }

        eprintln!(
            "locales: aapt2 reports the name in {} languages from the table this build wrote",
            translations.len() + 1
        );
        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_image_the_developer_chose_becomes_the_icon_aapt2_reports() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| super::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("icon: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-icon-package");
        let root = directory.join("Pictured");
        let text = root.to_str().unwrap().to_string();
        super::scaffold::create(&text, &super::scaffold::Spec::default()).unwrap();
        super::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();

        let project = super::builder::from_project(&text).unwrap();
        assert!(project.icon.is_some(), "the stored image must be read back");
        assert_eq!(
            project.launcher.len(),
            super::image::LAUNCHER_SIZES.len() * 2,
            "choosing the image wrote the launcher icons into the project's own folders"
        );

        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect("a project with an image must build");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).expect("it must read back");
        for wanted in [
            "AndroidManifest.xml",
            super::builder::TABLE_ENTRY,
            "classes.dex",
        ] {
            assert!(
                archive.entries().iter().any(|entry| entry.name == wanted),
                "the package must carry {wanted}"
            );
        }
        for (folder, edge) in super::image::LAUNCHER_SIZES {
            for name in ["ic_launcher", "ic_launcher_round"] {
                let wanted = format!("res/{folder}/{name}.png");
                let entry = archive
                    .entry(&wanted)
                    .unwrap_or_else(|| panic!("the package must carry {wanted}"));
                let bytes = archive.content(&outcome.package, entry).unwrap();
                let header = super::image::read_png(&bytes).unwrap();
                assert_eq!(header.width, *edge, "{wanted}");
                assert_eq!(header.height, *edge, "{wanted}");
            }
        }

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing"
            );
            eprintln!("icon: aapt2 is not available here");
            std::fs::remove_dir_all(&directory).ok();
            return;
        };

        let path = directory.join("pictured.apk");
        std::fs::write(&path, &outcome.package).unwrap();

        let badging = std::process::Command::new(&aapt2)
            .args(["dump", "badging", path.to_str().unwrap()])
            .output()
            .unwrap();
        let report = format!(
            "{}{}",
            String::from_utf8_lossy(&badging.stdout),
            String::from_utf8_lossy(&badging.stderr)
        );
        assert!(badging.status.success(), "{report}");
        for (folder, density) in [
            ("mipmap-mdpi", 160),
            ("mipmap-hdpi", 240),
            ("mipmap-xhdpi", 320),
            ("mipmap-xxhdpi", 480),
            ("mipmap-xxxhdpi", 640),
        ] {
            let wanted = format!("application-icon-{density}:'res/{folder}/ic_launcher.png'");
            assert!(
                report.contains(&wanted),
                "aapt2 must report {wanted}:\n{report}"
            );
        }

        let tree = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                path.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let manifest = String::from_utf8_lossy(&tree.stdout).to_string();
        assert!(tree.status.success(), "{manifest}");
        assert!(
            manifest.contains("android:icon(0x01010002)=@0x7f010000"),
            "the manifest must point at the identifier the table assigned:\n{manifest}"
        );
        assert!(
            manifest.contains("android:roundIcon(0x0101052c)=@0x7f010001"),
            "the round icon must be pointed at as well:\n{manifest}"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "icon: one {} byte image became {} launcher images across {} densities, square and \
             round, and aapt2 reports them as the application icon",
            project.icon.as_ref().map(|png| png.len()).unwrap_or(0),
            super::image::LAUNCHER_SIZES.len() * 2,
            super::image::LAUNCHER_SIZES.len(),
        );
    }

    #[test]
    fn a_package_this_build_writes_is_compressed_where_compressing_is_allowed() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let picture = files
            .into_iter()
            .find(|file| super::image::read_png_file(file.to_str().unwrap_or_default()).is_ok());

        let mut project = super::builder::starter("com.tr.yt", "Packed");
        project.icon = picture.as_ref().map(|path| std::fs::read(path).unwrap());
        project.files = vec![
            (
                "lib/arm64-v8a/libomni.so".to_string(),
                b"\x7fELF".iter().copied().cycle().take(64_000).collect(),
            ),
            (
                "assets/notes.txt".to_string(),
                "the same sentence over and over. ".repeat(400).into_bytes(),
            ),
        ];

        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();
        assert!(!sink.has_blocking(), "{:?}", sink.entries());

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).expect("it must read back");

        let table = archive.entry(super::builder::TABLE_ENTRY);
        if let Some(table) = table {
            assert_eq!(
                table.compression,
                archive::Compression::Stored,
                "Android maps the resource table in place, so it may never be compressed"
            );
            assert!(table.is_aligned_to(4));
        }

        let library = archive
            .entry("lib/arm64-v8a/libomni.so")
            .expect("the library must be there");
        assert_eq!(
            library.compression,
            archive::Compression::Stored,
            "a native library is loaded straight out of the package, so it stays stored"
        );
        assert!(library.is_aligned_to(super::builder::PAGE_ALIGNMENT));

        let notes = archive
            .entry("assets/notes.txt")
            .expect("the asset must be there");
        assert_eq!(
            notes.compression,
            archive::Compression::Deflate,
            "a repetitive asset is exactly what compression is for"
        );
        assert!(
            notes.compressed_size * 4 < notes.uncompressed_size,
            "{} bytes out of {} is not compression",
            notes.compressed_size,
            notes.uncompressed_size
        );

        for entry in archive.entries() {
            let read = archive
                .content(&outcome.package, entry)
                .unwrap_or_else(|error| panic!("{}: {} {}", entry.name, error.code, error.message));
            assert_eq!(read.len() as u64, entry.uncompressed_size, "{}", entry.name);
        }

        let directory = temp_directory("omni-packed");
        let path = directory.join("packed.apk");
        std::fs::write(&path, &outcome.package).unwrap();

        let listed = std::process::Command::new("unzip")
            .args(["-p", path.to_str().unwrap(), "assets/notes.txt"])
            .output()
            .unwrap();
        assert!(listed.status.success());
        assert_eq!(
            listed.stdout,
            "the same sentence over and over. ".repeat(400).into_bytes(),
            "an independent reader must get back exactly what went in"
        );

        if let Some(zipalign) = find_build_tool("zipalign") {
            let checked = std::process::Command::new(&zipalign)
                .args(["-c", "-P", "16", "-v", "4", path.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                checked.status.success(),
                "zipalign refused it:\n{}{}",
                String::from_utf8_lossy(&checked.stdout),
                String::from_utf8_lossy(&checked.stderr)
            );
        }

        let stored: u64 = archive
            .entries()
            .iter()
            .map(|entry| entry.uncompressed_size)
            .sum();
        let packed: u64 = archive
            .entries()
            .iter()
            .map(|entry| entry.compressed_size)
            .sum();
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "archive: {} entries, {stored} bytes of content carried in {packed}, with the \
             resource table and the native library left stored and aligned",
            archive.entries().len()
        );
    }

    #[test]
    fn the_resource_table_sits_where_the_installer_needs_it() {
        let mut files = Vec::new();
        for candidate in [
            std::env::var("ANDROID_HOME").ok(),
            Some("/usr/share/icons".to_string()),
        ]
        .into_iter()
        .flatten()
        {
            let path = std::path::PathBuf::from(candidate);
            if path.is_dir() {
                gather_png_files(&path, &mut files, 8);
            }
        }
        let Some(source) = files
            .into_iter()
            .find(|file| super::image::read_png_file(file.to_str().unwrap_or_default()).is_ok())
        else {
            eprintln!("alignment: no PNG file is available here");
            return;
        };

        let directory = temp_directory("omni-arsc-align");
        let root = directory.join("Aligned");
        let text = root.to_str().unwrap().to_string();
        super::scaffold::create(&text, &super::scaffold::Spec::default()).unwrap();
        super::scaffold::set_icon(&text, source.to_str().unwrap()).unwrap();

        let project = super::builder::from_project(&text).unwrap();
        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let outcome = super::builder::build(&project, &key, 1_787_000_000, &mut sink).unwrap();

        let mut own = Sink::new();
        let archive = archive::read(&outcome.package, &mut own).unwrap();
        let table = archive
            .entry(super::builder::TABLE_ENTRY)
            .expect("the table must be in the package");
        assert_eq!(
            table.compression,
            archive::Compression::Stored,
            "Android reads resources.arsc in place, so it may not be compressed"
        );
        assert!(
            table.is_aligned_to(4),
            "Android maps resources.arsc directly, so it must start on a four byte boundary"
        );

        let path = directory.join("aligned.apk");
        std::fs::write(&path, &outcome.package).unwrap();
        if let Some(zipalign) = find_build_tool("zipalign") {
            let checked = std::process::Command::new(&zipalign)
                .args(["-c", "-v", "4", path.to_str().unwrap()])
                .output()
                .unwrap();
            assert!(
                checked.status.success(),
                "zipalign refused it:\n{}{}",
                String::from_utf8_lossy(&checked.stdout),
                String::from_utf8_lossy(&checked.stderr)
            );
            eprintln!("alignment: zipalign agrees the package is aligned at four bytes");
        }

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_manifest_that_names_a_resource_this_build_has_no_table_for_is_refused() {
        let key = super::rsa::generate(2048).unwrap();
        let mut sink = Sink::new();
        let mut project = super::builder::starter("com.tr.yt", "Named");
        project.manifest = project.manifest.replace(
            "android:label=\"Named\"",
            "android:label=\"@string/app_name\"",
        );

        let refused = super::builder::build(&project, &key, 1_787_000_000, &mut sink)
            .expect_err("a name with no identifier behind it must be refused");
        assert_eq!(refused.code, "EB042");
        assert!(
            refused
                .context
                .iter()
                .any(|line| line.contains("@string/app_name")),
            "{:?}",
            refused.context
        );
    }

    #[test]
    fn this_application_meets_the_policy_it_enforces_on_what_it_builds() {
        let mut candidates: Vec<std::path::PathBuf> = Vec::new();
        for variant in ["release"] {
            for shape in ["merged_manifest", "merged_manifests"] {
                let mut root = std::path::PathBuf::from("Builder/build/intermediates");
                root.push(shape);
                root.push(variant);
                let Ok(entries) = std::fs::read_dir(&root) else {
                    continue;
                };
                for entry in entries.flatten() {
                    let path = entry.path().join("AndroidManifest.xml");
                    if path.is_file() {
                        candidates.push(path);
                    }
                }
            }
        }

        if candidates.is_empty() {
            assert!(
                std::env::var("OMNI_REQUIRE_SELF_POLICY").is_err(),
                "OMNI_REQUIRE_SELF_POLICY is set but no merged manifest was found, so this \
                 application was never held to the policy it enforces on what it builds"
            );
            eprintln!("self policy: no merged manifest has been produced here");
            return;
        }

        // The one thing this application is allowed that what it builds is not.
        // Installing the package it has just written is the whole point of the
        // button that offers to; the permission cannot be avoided, and Android
        // still asks the person once per source before anything is installed.
        // Every other rule applies here exactly as it applies to a project.
        const OWN_EXCEPTION: &str = "android.permission.REQUEST_INSTALL_PACKAGES";

        for path in &candidates {
            let text = std::fs::read_to_string(path).unwrap();
            let mut sink = Sink::new();
            let root = super::xml::parse(&text, "AndroidManifest.xml", &mut sink)
                .unwrap_or_else(|| panic!("{} must parse", path.display()));
            let report = super::guard::inspect_manifest(&root);

            let unexpected: Vec<String> = report
                .findings
                .iter()
                .filter(|finding| !finding.what.contains(OWN_EXCEPTION))
                .map(|finding| format!("{}: {} {}", finding.code, finding.what, finding.remedy))
                .collect();
            assert!(
                unexpected.is_empty(),
                "{} is refused by the policy this build applies to others:\n{}",
                path.display(),
                unexpected.join("\n")
            );
            assert!(report.rules_applied >= 7);
        }

        // The exception is this application's alone. A project asking for the
        // same permission is still refused, so the rule keeps its teeth where
        // it matters.
        let asking = format!(
            "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n\
             <manifest xmlns:android=\"http://schemas.android.com/apk/res/android\" \
             package=\"com.my.app\">\n\
             <uses-permission android:name=\"{OWN_EXCEPTION}\" />\n\
             <application android:label=\"L\" android:allowBackup=\"false\" \
             android:hasCode=\"false\" android:extractNativeLibs=\"false\" />\n\
             </manifest>"
        );
        let mut sink = Sink::new();
        let root = super::xml::parse(&asking, "AndroidManifest.xml", &mut sink).unwrap();
        let report = super::guard::inspect_manifest(&root);
        assert_eq!(report.verdict(), super::guard::Verdict::Refused);
        assert!(
            report
                .findings
                .iter()
                .any(|finding| finding.code == "EG007"),
            "{:?}",
            report.findings
        );

        eprintln!(
            "self policy: {} release manifest(s) of this application pass the rules it \
             enforces, but for {OWN_EXCEPTION}, which it holds so it can install what it \
             builds and which it still refuses in every project. The debug manifest is \
             deliberately not checked: it is marked debuggable, which is what EG001 exists \
             to refuse, and it is never the artifact this build publishes.",
            candidates.len()
        );
    }

    #[test]
    fn a_name_with_xml_in_it_survives_the_manifest_intact() {
        let chosen = "Ali & <Veli> \"Co\"";
        let spec = super::scaffold::Spec {
            label: chosen.to_string(),
            version_name: "1.0.0".to_string(),
            version_code: 7,
            ..super::scaffold::Spec::default()
        };
        let text = spec.manifest();
        assert!(text.contains("android:versionCode=\"7\""), "{text}");
        assert!(text.contains("android:versionName=\"1.0.0\""), "{text}");

        let mut sink = Sink::new();
        let root = super::xml::parse(&text, "AndroidManifest.xml", &mut sink)
            .expect("a name with markup in it must still produce a manifest that reads back");
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        let application = root
            .children
            .iter()
            .find(|child| child.name == "application")
            .unwrap();
        assert_eq!(
            application.attribute("android:label").unwrap(),
            format!("@string/{}", super::scaffold::LABEL_RESOURCE),
            "the name lives in the values folders now, so the manifest points at it"
        );

        let mut table = ResourceTable::new();
        let mut sink = Sink::new();
        for (folder, body) in spec.values_files() {
            let config = super::resources::Config::parse_values_directory(&folder).unwrap();
            assert!(
                table.read_values_for(&body, &folder, config, &mut sink),
                "{:?}",
                sink.entries()
            );
        }
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        for entry in table.entries() {
            assert_eq!(
                entry.value,
                super::resources::Value::Text(chosen.to_string()),
                "the markup in the name survives the escaping in {}",
                entry.config
            );
        }
    }

