    #[test]
    fn the_bridge_makes_a_developer_key_lists_it_and_signs_a_project_with_it() {
        let directory = temp_directory("omni-ffi-keys");
        let keys = directory.join("Keys");
        let root = directory.join("Signed");
        super::scaffold::create(root.to_str().unwrap(), &super::scaffold::Spec::default()).unwrap();

        let keys_c = std::ffi::CString::new(keys.to_str().unwrap()).unwrap();
        let spec_c = std::ffi::CString::new(
            "alias=studio;commonName=Studio Name;organisation=Omni;country=TR;\
             validityDays=10950;bits=2048",
        )
        .unwrap();
        let password_c = std::ffi::CString::new("a password worth having").unwrap();

        let made = call_ffi(|| unsafe {
            super::ffi::omni_create_key(keys_c.as_ptr(), spec_c.as_ptr(), password_c.as_ptr())
        });
        assert!(is_structurally_valid(&made), "{made}");
        assert!(made.contains("\"created\":true"), "{made}");
        assert!(made.contains("CN=Studio Name"), "{made}");

        let listed = call_ffi(|| unsafe { super::ffi::omni_list_keys(keys_c.as_ptr()) });
        assert!(is_structurally_valid(&listed), "{listed}");
        assert!(listed.contains("\"alias\":\"studio\""), "{listed}");

        let path = super::keystore::path_for(keys.to_str().unwrap(), "studio");
        let path_c = std::ffi::CString::new(path.clone()).unwrap();
        let opened = call_ffi(|| unsafe {
            super::ffi::omni_check_key(path_c.as_ptr(), password_c.as_ptr())
        });
        assert!(opened.contains("\"opened\":true"), "{opened}");

        let wrong_c = std::ffi::CString::new("not the password").unwrap();
        let refused =
            call_ffi(|| unsafe { super::ffi::omni_check_key(path_c.as_ptr(), wrong_c.as_ptr()) });
        assert!(refused.contains("\"opened\":false"), "{refused}");
        assert!(refused.contains("EY021"), "{refused}");
        assert!(
            !refused.contains("not the password"),
            "a bridge answer must never echo a password: {refused}"
        );

        let output = directory.join("signed.apk");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let out_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let built = call_ffi(|| unsafe {
            super::ffi::omni_build_project(
                root_c.as_ptr(),
                out_c.as_ptr(),
                path_c.as_ptr(),
                password_c.as_ptr(),
            )
        });
        assert!(is_structurally_valid(&built), "{built}");
        assert!(built.contains("\"built\":true"), "{built}");
        assert!(built.contains("\"developerKey\":true"), "{built}");
        assert!(built.contains("CN=Studio Name"), "{built}");
        assert!(
            !built.contains("a password worth having"),
            "a build answer must never echo a password: {built}"
        );

        let bytes = std::fs::read(&output).unwrap();
        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).unwrap();
        let report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        assert!(report.schemes.contains(&"v2"), "{:?}", report.schemes);
        assert!(report.schemes.contains(&"v3"), "{:?}", report.schemes);
        assert!(report.signers[0].certificates[0]
            .subject
            .contains("CN=Studio Name"));

        let removed = call_ffi(|| unsafe { super::ffi::omni_delete_key(path_c.as_ptr()) });
        assert!(removed.contains("\"removed\":true"), "{removed}");
        assert!(super::keystore::list(keys.to_str().unwrap()).is_empty());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_picture_with_more_colours_than_a_palette_holds_is_cut_down_where_it_can_be() {
        // Flat artwork photographed, or drawn with a soft brush: a few dozen
        // colours the eye sees, and thousands the file holds because every pixel
        // is off by a shade or two. The shades are what puts it past a palette,
        // and they are also what nobody can see.
        let edge = 192u32;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        let mut seed = 0x2545_F491_4F6C_DD1Du64;
        let mut wobble = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            ((seed >> 33) % 5) as i16 - 2
        };
        for y in 0..edge {
            for x in 0..edge {
                let group = ((x / 24) + (y / 24) * 8) % 64;
                let shade = |base: u32, by: i16| (base as i16 + by).clamp(0, 255) as u8;
                pixels.extend_from_slice(&[
                    shade(30 + group % 8 * 28, wobble()),
                    shade(20 + group / 8 * 28, wobble()),
                    shade(200 - group % 5 * 40, wobble()),
                    255,
                ]);
            }
        }
        let raster = super::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };

        assert!(
            super::image::palette_of(&raster).is_none(),
            "this picture is meant to hold more colours than a palette does"
        );

        let palette = super::image::quantise(&raster, super::image::LARGEST_PALETTE);
        assert!(palette.len() >= 2 && palette.len() <= super::image::LARGEST_PALETTE);
        let error = super::image::error_against(&raster, &palette);
        assert!(
            error <= super::image::INVISIBLE_ERROR,
            "the cut moved the picture by {error}, past what an eye cannot find"
        );

        let exact = super::image::encode(&raster).unwrap();
        let written = super::image::encode_smallest(&raster).unwrap();
        assert_eq!(
            super::image::decode(&exact).unwrap().pixels,
            raster.pixels,
            "the encoder that is not asked to squeeze stays exact"
        );
        assert!(
            written.len() * 2 < exact.len(),
            "the squeeze must be worth having: {} against {}",
            written.len(),
            exact.len()
        );

        let read = super::image::decode(&written).unwrap();
        assert_eq!(read.width, raster.width);
        assert_eq!(read.height, raster.height);
        assert!(
            super::image::error_against(&read, &palette) <= super::image::INVISIBLE_ERROR,
            "what was written reads back as the picture that went in"
        );

        eprintln!(
            "quantise: thousands of colours became {}, {} bytes became {} ({}%), \
             mean squared error {error:.3}",
            palette.len(),
            exact.len(),
            written.len(),
            written.len() * 100 / exact.len(),
        );
    }

    #[test]
    fn a_picture_a_palette_would_spoil_keeps_every_colour_it_came_with() {
        // A smooth sweep across all three channels: cutting this to 256 colours
        // bands it visibly, so the encoder must leave it alone.
        let edge = 128u32;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        for y in 0..edge {
            for x in 0..edge {
                pixels.extend_from_slice(&[(x * 2) as u8, (y * 2) as u8, (x + y) as u8, 255]);
            }
        }
        let raster = super::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };

        let palette = super::image::quantise(&raster, super::image::LARGEST_PALETTE);
        let error = super::image::error_against(&raster, &palette);
        assert!(
            error > super::image::INVISIBLE_ERROR,
            "a sweep this wide cannot survive 256 colours, yet the error was {error}"
        );

        let written = super::image::encode_smallest(&raster).unwrap();
        let read = super::image::decode(&written).unwrap();
        assert_eq!(
            read.pixels, raster.pixels,
            "a picture the palette would spoil is written exactly as it came"
        );
        eprintln!("quantise: refused, the cut would have moved the picture by {error:.1}");
    }

    #[test]
    fn what_is_clear_in_a_picture_is_still_clear_after_it_is_squeezed() {
        // A round icon: a busy disc on nothing at all. The corners are what an
        // eye notices if a squeeze gets it wrong, because a corner that came
        // back one step short of clear draws a square edge around the icon.
        let edge = 128u32;
        let middle = (edge as f64 - 1.0) / 2.0;
        let radius = middle;
        let mut pixels = Vec::with_capacity((edge * edge * 4) as usize);
        let mut seed = 0x9E37_79B9_7F4A_7C15u64;
        let mut wobble = || {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            ((seed >> 33) % 7) as i16 - 3
        };
        for y in 0..edge {
            for x in 0..edge {
                let across = f64::from(x) - middle;
                let down = f64::from(y) - middle;
                let shade = |base: u32, by: i16| (base as i16 + by).clamp(0, 255) as u8;
                if across * across + down * down <= radius * radius {
                    let group = ((x / 16) + (y / 16) * 8) % 64;
                    pixels.extend_from_slice(&[
                        shade(40 + group % 8 * 26, wobble()),
                        shade(30 + group / 8 * 26, wobble()),
                        shade(190 - group % 5 * 34, wobble()),
                        255,
                    ]);
                } else {
                    // The channels under a clear pixel are whatever a tool left
                    // there. They must not reach the palette, and they must not
                    // come back.
                    pixels.extend_from_slice(&[220, 40, 90, 0]);
                }
            }
        }
        let raster = super::image::Raster {
            width: edge,
            height: edge,
            pixels,
        };
        assert!(
            super::image::palette_of(&raster).is_none(),
            "this picture is meant to hold more colours than a palette does"
        );

        let written = super::image::encode_smallest(&raster).unwrap();
        let exact = super::image::encode(&raster).unwrap();
        assert!(
            written.len() < exact.len(),
            "a picture like this must squeeze: {} against {}",
            written.len(),
            exact.len()
        );

        let read = super::image::decode(&written).unwrap();
        assert_eq!(read.width, edge);
        assert_eq!(read.height, edge);

        let mut clear = 0usize;
        for y in 0..edge {
            for x in 0..edge {
                let across = f64::from(x) - middle;
                let down = f64::from(y) - middle;
                let outside = across * across + down * down > radius * radius;
                let alpha = read.at(x, y)[3];
                if outside {
                    assert_eq!(
                        alpha, 0,
                        "the corner at {x},{y} came back {alpha}, not clear"
                    );
                    clear += 1;
                } else {
                    assert_eq!(
                        alpha, 255,
                        "the disc at {x},{y} came back {alpha}, not solid"
                    );
                }
            }
        }
        assert!(clear > 0, "the picture must have somewhere clear to test");
        eprintln!(
            "quantise: {clear} clear pixels stayed clear, {} bytes became {}",
            exact.len(),
            written.len()
        );
    }

    #[test]
    fn a_second_project_is_never_written_over_the_first() {
        let directory = temp_directory("omni-two-projects");
        let root = directory.join("Same Name");
        let text = root.to_str().unwrap().to_string();

        let first = super::scaffold::Spec {
            package: "com.my.first".to_string(),
            label: "First".to_string(),
            ..super::scaffold::Spec::default()
        };
        super::scaffold::create(&text, &first).unwrap();
        let written = std::fs::read_to_string(root.join("AndroidManifest.xml")).unwrap();

        let second = super::scaffold::Spec {
            package: "com.my.second".to_string(),
            label: "Second".to_string(),
            ..super::scaffold::Spec::default()
        };
        let refused = super::scaffold::create(&text, &second)
            .expect_err("a project may not be written into a folder that holds one");
        assert_eq!(refused.code, "EP028");
        assert_eq!(
            std::fs::read_to_string(root.join("AndroidManifest.xml")).unwrap(),
            written,
            "the first project's manifest is the one still there"
        );
        assert_eq!(
            super::workspace::list_projects(directory.to_str().unwrap()).len(),
            1
        );

        let beside = directory.join("Same Name 2");
        super::scaffold::create(beside.to_str().unwrap(), &second).unwrap();
        let listed = super::workspace::list_projects(directory.to_str().unwrap());
        assert_eq!(listed.len(), 2, "{listed:?}");
        let packages: Vec<&str> = listed.iter().map(|one| one.package.as_str()).collect();
        assert!(packages.contains(&"com.my.first"), "{packages:?}");
        assert!(packages.contains(&"com.my.second"), "{packages:?}");

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_build_without_a_password_never_writes_over_a_sealed_key() {
        // Makes a key at the shared alias, so it has to take its turn with
        // whatever else is moving the device binding.
        let _turn = SHARED_KEY_TURN
            .lock()
            .unwrap_or_else(|held| held.into_inner());
        let directory = temp_directory("omni-key-kept");
        let keys = directory.join("Keys");
        let path =
            super::keystore::path_for(keys.to_str().unwrap(), super::keystore::DEFAULT_ALIAS);
        super::keystore::create(
            keys.to_str().unwrap(),
            &super::keystore::Request::default(),
            super::keystore::DEFAULT_PASSWORD,
            1_787_000_000,
        )
        .unwrap();
        let sealed = std::fs::read(&path).unwrap();

        let error = super::builder::signing_key(&path)
            .expect_err("a sealed key is not a key this path may open");
        assert_eq!(error.code, "EB021");
        assert_eq!(
            std::fs::read(&path).unwrap(),
            sealed,
            "the key on disk is the key that was there before"
        );

        let root = directory.join("Kept");
        super::scaffold::create(root.to_str().unwrap(), &super::scaffold::Spec::default()).unwrap();
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let package_c =
            std::ffi::CString::new(directory.join("kept.apk").to_str().unwrap()).unwrap();
        let bundle_c =
            std::ffi::CString::new(directory.join("kept.aab").to_str().unwrap()).unwrap();
        let path_c = std::ffi::CString::new(path.clone()).unwrap();

        let refused = call_ffi(|| unsafe {
            super::ffi::omni_build_all(
                root_c.as_ptr(),
                package_c.as_ptr(),
                bundle_c.as_ptr(),
                path_c.as_ptr(),
                std::ptr::null(),
            )
        });
        assert!(is_structurally_valid(&refused), "{refused}");
        assert!(refused.contains("\"built\":false"), "{refused}");
        assert!(refused.contains("EB021"), "{refused}");
        assert_eq!(
            std::fs::read(&path).unwrap(),
            sealed,
            "a build asked for without the password leaves the key alone"
        );
        assert!(super::keystore::describe(&path).is_ok());

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn the_shared_key_is_made_once_and_signs_the_package_and_the_bundle_together() {
        let _turn = SHARED_KEY_TURN
            .lock()
            .unwrap_or_else(|held| held.into_inner());
        let directory = temp_directory("omni-shared-key");
        let keys = directory.join("Keys");
        let root = directory.join("Together");
        super::scaffold::create(root.to_str().unwrap(), &super::scaffold::Spec::default()).unwrap();

        let keys_c = std::ffi::CString::new(keys.to_str().unwrap()).unwrap();
        let first = call_ffi(|| unsafe { super::ffi::omni_default_key(keys_c.as_ptr()) });
        assert!(is_structurally_valid(&first), "{first}");
        assert!(first.contains("\"ready\":true"), "{first}");
        assert!(first.contains("\"created\":true"), "{first}");
        assert!(
            first.contains(&format!("CN={}", super::keystore::DEFAULT_COMMON_NAME)),
            "{first}"
        );
        assert!(
            first.contains(&format!("O={}", super::keystore::DEFAULT_ORGANISATION)),
            "{first}"
        );
        assert!(
            first.contains(&format!("C={}", super::keystore::DEFAULT_COUNTRY)),
            "{first}"
        );
        assert!(
            first.contains(&format!("\"bits\":{}", super::keystore::DEFAULT_BITS)),
            "{first}"
        );
        assert!(
            !first.contains(super::keystore::DEFAULT_PASSWORD),
            "an answer must never echo a password: {first}"
        );

        let again = call_ffi(|| unsafe { super::ffi::omni_default_key(keys_c.as_ptr()) });
        assert!(again.contains("\"ready\":true"), "{again}");
        assert!(
            again.contains("\"created\":false"),
            "the shared key is made once and reused after that: {again}"
        );
        assert_eq!(super::keystore::list(keys.to_str().unwrap()).len(), 1);

        let path =
            super::keystore::path_for(keys.to_str().unwrap(), super::keystore::DEFAULT_ALIAS);
        assert!(super::keystore::is_default(&path));

        let package = directory.join("together.apk");
        let bundle = directory.join("together.aab");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let package_c = std::ffi::CString::new(package.to_str().unwrap()).unwrap();
        let bundle_c = std::ffi::CString::new(bundle.to_str().unwrap()).unwrap();
        let path_c = std::ffi::CString::new(path.clone()).unwrap();
        let password_c = std::ffi::CString::new(super::keystore::DEFAULT_PASSWORD).unwrap();

        let built = call_ffi(|| unsafe {
            super::ffi::omni_build_all(
                root_c.as_ptr(),
                package_c.as_ptr(),
                bundle_c.as_ptr(),
                path_c.as_ptr(),
                password_c.as_ptr(),
            )
        });
        assert!(is_structurally_valid(&built), "{built}");
        assert!(built.contains("\"built\":true"), "{built}");
        assert!(built.contains("\"developerKey\":true"), "{built}");
        assert!(
            built.contains(&format!("\"locales\":{}", super::scaffold::LOCALES.len())),
            "one action carries every language folder the project holds: {built}"
        );
        assert!(
            !built.contains(super::keystore::DEFAULT_PASSWORD),
            "a build answer must never echo a password: {built}"
        );

        let bytes = std::fs::read(&package).unwrap();
        let mut sink = Sink::new();
        let read = archive::read(&bytes, &mut sink).unwrap();
        let report = signing::examine(
            &bytes,
            read.central_directory_offset(),
            read.end_record_offset(),
            &mut sink,
        );
        assert!(report.schemes.contains(&"v2"), "{:?}", report.schemes);
        assert!(report.signers[0].certificates[0]
            .subject
            .contains(&format!("CN={}", super::keystore::DEFAULT_COMMON_NAME)));

        let bundled = std::fs::read(&bundle).unwrap();
        let read = archive::read(&bundled, &mut Sink::new()).unwrap();
        assert!(
            read.entry(super::bundle::MANIFEST_ENTRY).is_some(),
            "the bundle the same action wrote holds its manifest"
        );

        let listed = super::workspace::list_built(directory.to_str().unwrap());
        assert_eq!(listed.len(), 2, "{listed:?}");
        assert!(listed.iter().any(|made| made.bundle));
        assert!(listed.iter().any(|made| !made.bundle));

        std::fs::remove_dir_all(&directory).ok();
    }

    #[test]
    fn a_package_checks_itself_and_says_what_it_found() {
        let directory = temp_directory("omni-integrity");
        let root = directory.join("Checked");
        super::scaffold::create(root.to_str().unwrap(), &super::scaffold::Spec::default()).unwrap();

        let output = directory.join("checked.apk");
        let key = directory.join("signing.pk8");
        let root_c = std::ffi::CString::new(root.to_str().unwrap()).unwrap();
        let out_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let key_c = std::ffi::CString::new(key.to_str().unwrap()).unwrap();
        call_ffi(|| unsafe {
            super::ffi::omni_build_project(
                root_c.as_ptr(),
                out_c.as_ptr(),
                key_c.as_ptr(),
                std::ptr::null(),
            )
        });

        let bytes = std::fs::read(&output).unwrap();
        let mut sink = Sink::new();
        let archive = archive::read(&bytes, &mut sink).unwrap();
        let signing_report = signing::examine(
            &bytes,
            archive.central_directory_offset(),
            archive.end_record_offset(),
            &mut sink,
        );
        let fingerprint = signing_report.signers[0].certificates[0]
            .fingerprint
            .to_hex();

        let path_c = std::ffi::CString::new(output.to_str().unwrap()).unwrap();
        let good = std::ffi::CString::new(fingerprint.clone()).unwrap();
        let report =
            call_ffi(|| unsafe { super::ffi::omni_verify_self(path_c.as_ptr(), good.as_ptr()) });
        assert!(report.contains("\"standing\":\"TRUSTED\""), "{report}");
        assert!(
            report.contains("cannot detect an attacker who patched the check out"),
            "{report}"
        );

        let other = std::ffi::CString::new("0".repeat(64)).unwrap();
        let report =
            call_ffi(|| unsafe { super::ffi::omni_verify_self(path_c.as_ptr(), other.as_ptr()) });
        assert!(report.contains("\"standing\":\"TAMPERED\""), "{report}");
        assert!(report.contains("signed by a different key"), "{report}");

        let mut damaged = bytes.clone();
        let at = damaged.len() / 3;
        damaged[at] ^= 0xff;
        let damaged_path = directory.join("damaged.apk");
        std::fs::write(&damaged_path, &damaged).unwrap();
        let damaged_c = std::ffi::CString::new(damaged_path.to_str().unwrap()).unwrap();
        let report =
            call_ffi(|| unsafe { super::ffi::omni_verify_self(damaged_c.as_ptr(), good.as_ptr()) });
        assert!(report.contains("\"standing\":\"TAMPERED\""), "{report}");

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("integrity: a signed package reports TRUSTED, a re-signed or edited one reports TAMPERED");
    }

    fn bytes_of(hex: &str) -> Vec<u8> {
        (0..hex.len())
            .step_by(2)
            .map(|at| u8::from_str_radix(&hex[at..at + 2], 16).unwrap())
            .collect()
    }

    fn hex_string(bytes: &[u8]) -> String {
        bytes.iter().map(|byte| format!("{byte:02x}")).collect()
    }

    /// A compiler that does whatever a test needs it to, so that the contract
    /// can be held to its promises without a real one in the way.
    struct Pretend {
        outputs: Vec<(String, super::compiler::Kind, Vec<u8>)>,
        /// What it actually offers, when that is meant to differ from the plan.
        offers: Option<Vec<(String, super::compiler::Kind, Vec<u8>)>>,
        stop_after: Option<usize>,
        stopper: std::sync::Mutex<Option<super::compiler::Stopper>>,
    }

    static PRETEND_CONTRACT: super::plugin::Contract = super::plugin::Contract {
        id: "omni.plugin.pretend",
        display_name: "Pretend",
        version: super::plugin::Version::new(0, 1, 0),
        status: super::Status::Experimental,
        summary: "A compiler that exists so the contract can be tested.",
        inputs: &["pretend.source"],
        outputs: &["jvm.class"],
        required_capabilities: &[super::caps::Capability::TempStorage],
        forbidden_capabilities: &[super::caps::Capability::Network],
        non_responsibilities: &["Compiling anything."],
    };

    impl super::compiler::Compiler for Pretend {
        fn contract(&self) -> &'static super::plugin::Contract {
            &PRETEND_CONTRACT
        }

        fn probe(&self) -> super::compiler::Probe {
            super::compiler::Probe::usable(
                super::compiler::Identity::new("pretend", "pretend", "1.0.0", "any"),
                super::compiler::Reproducibility::Always,
            )
        }

        fn plan(
            &self,
            request: &super::compiler::Request,
        ) -> Result<super::compiler::Plan, super::diag::Diagnostic> {
            let identity = self.probe().identity.unwrap();
            Ok(super::compiler::Plan {
                key: super::compiler::Plan::key_for(&identity, request),
                identity,
                expected: self
                    .outputs
                    .iter()
                    .map(|(name, kind, _)| super::compiler::Expected {
                        name: name.clone(),
                        kind: *kind,
                    })
                    .collect(),
                reproducibility: super::compiler::Reproducibility::Always,
            })
        }

        fn compile(
            &self,
            plan: &super::compiler::Plan,
            _request: &super::compiler::Request,
            mut session: super::compiler::Session<'_>,
        ) -> Result<super::compiler::Compiled, super::diag::Diagnostic> {
            let offering = self.offers.as_ref().unwrap_or(&self.outputs);
            for (index, (name, kind, bytes)) in offering.iter().enumerate() {
                if self.stop_after == Some(index) {
                    // Taken out and put back, so the guard is gone before the
                    // stop happens. Holding a lock across anything else is how
                    // the first version of this test deadlocked against itself.
                    let stopper = self.stopper.lock().unwrap().clone();
                    if let Some(stopper) = stopper {
                        stopper.stop();
                    }
                }
                session.offer(name.clone(), *kind, bytes.clone())?;
            }
            session.commit(plan)
        }
    }

    fn pretend(outputs: Vec<(&str, super::compiler::Kind, &[u8])>) -> Pretend {
        Pretend {
            outputs: outputs
                .into_iter()
                .map(|(name, kind, bytes)| (name.to_string(), kind, bytes.to_vec()))
                .collect(),
            offers: None,
            stop_after: None,
            stopper: std::sync::Mutex::new(None),
        }
    }

    #[test]
    fn nothing_a_compiler_made_is_published_unless_all_of_it_was() {
        use super::compiler::{Budget, Compiler, Kind, Request, Session};

        let directory = temp_directory("omni-compiler-contract");
        let store = super::store::Store::at(directory.to_str().unwrap());
        let request = Request::new(super::compiler::Abi::Arm64V8a, 28)
            .with_source(super::compiler::Source::of("A.java", b"class A {}"));

        let session_of = |budget: Budget| {
            let policy: &'static mut super::caps::Policy =
                Box::leak(Box::new(super::caps::Policy::new("test")));
            let sink: &'static mut super::diag::Sink =
                Box::leak(Box::new(super::diag::Sink::new()));
            Session::new("omni.plugin.pretend", &store, policy, sink, budget)
        };

        // A compilation that runs to the end publishes everything, and each one
        // is read back out of the store and checked before it is called an
        // artifact.
        let good = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        let plan = good.plan(&request).unwrap();
        let compiled = good
            .compile(&plan, &request, session_of(Budget::default()))
            .expect("a compilation that finishes must publish");
        assert_eq!(compiled.produced.len(), 2);
        assert_eq!(compiled.key, plan.key);
        for one in &compiled.produced {
            assert!(store.has(one.digest), "{} must be in the store", one.name);
        }
        let held_after_success = store.list().len();
        assert_eq!(held_after_success, 2);

        // A compilation that produces less than it planned publishes nothing.
        // The half it did produce looks exactly like the half of a compilation
        // that worked, and this is the only moment anybody can tell.
        let mut short = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        short.offers = Some(vec![(
            "A.class".to_string(),
            Kind::JvmClass,
            b"one".to_vec(),
        )]);
        let plan = short.plan(&request).unwrap();
        let refused = short
            .compile(&plan, &request, session_of(Budget::default()))
            .expect_err("a compilation that did not keep its plan must publish nothing");
        assert_eq!(refused.code, "EX005");
        assert_eq!(
            store.list().len(),
            held_after_success,
            "nothing new may have reached the store"
        );

        // Something it never planned to make is refused too, whatever it is.
        let mut extra = pretend(vec![("A.class", Kind::JvmClass, b"one")]);
        extra.offers = Some(vec![(
            "Surprise.class".to_string(),
            Kind::JvmClass,
            b"one".to_vec(),
        )]);
        let plan = extra.plan(&request).unwrap();
        assert_eq!(
            extra
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("an unplanned output must be refused")
                .code,
            "EX006"
        );

        // And something of the wrong kind, which is how a plan stops being a
        // promise about what will exist and starts being a wish.
        let mut wrong = pretend(vec![("A.class", Kind::JvmClass, b"one")]);
        wrong.offers = Some(vec![("A.class".to_string(), Kind::Dex, b"one".to_vec())]);
        let plan = wrong.plan(&request).unwrap();
        assert_eq!(
            wrong
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("the wrong kind must be refused")
                .code,
            "EX007"
        );

        // Told to stop, it stops, and nothing it had made is published.
        let mut cancelled = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("B.class", Kind::JvmClass, b"two"),
        ]);
        cancelled.stop_after = Some(1);
        let plan = cancelled.plan(&request).unwrap();
        let budget = Budget::default();
        *cancelled.stopper.lock().unwrap() = Some(budget.stopper());
        let stopped = cancelled
            .compile(&plan, &request, session_of(budget))
            .expect_err("a compilation that was stopped must publish nothing");
        assert_eq!(stopped.code, "EX001");
        assert_eq!(store.list().len(), held_after_success);

        // Past what it was allowed to produce, it is refused. A build on a
        // device shares that device with whatever the person is doing.
        let big = pretend(vec![("A.class", Kind::JvmClass, b"more than four bytes")]);
        let plan = big.plan(&request).unwrap();
        assert_eq!(
            big.compile(&plan, &request, session_of(Budget::of(300, 4)))
                .expect_err("past its budget must be refused")
                .code,
            "EX004"
        );
        assert_eq!(store.list().len(), held_after_success);

        // Two things under one name is a mistake in the compiler, not a choice
        // about which one to keep.
        let mut twice = pretend(vec![
            ("A.class", Kind::JvmClass, b"one"),
            ("A.class", Kind::JvmClass, b"two"),
        ]);
        twice.offers = Some(vec![
            ("A.class".to_string(), Kind::JvmClass, b"one".to_vec()),
            ("A.class".to_string(), Kind::JvmClass, b"two".to_vec()),
        ]);
        let plan = twice.plan(&request).unwrap();
        assert_eq!(
            twice
                .compile(&plan, &request, session_of(Budget::default()))
                .expect_err("one name twice must be refused")
                .code,
            "EX003"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "contract: a compilation publishes all of what it planned or none of it, \
             and every published byte is read back and checked"
        );
    }

    #[test]
    fn the_same_everything_plans_to_the_same_key_and_anything_else_does_not() {
        use super::compiler::{Abi, Identity, Plan, Request, Source};

        let identity = Identity::new("kotlin", "omni.kotlin", "2.4.10", "aarch64-linux-android");
        let base = Request::new(Abi::Arm64V8a, 30)
            .with_source(Source::of("A.kt", b"fun main() {}"))
            .with_source(Source::of("B.kt", b"fun other() {}"));

        // The invariant, stated: the same canonical source, dependencies,
        // identity and configuration come to the same key.
        assert_eq!(
            Plan::key_for(&identity, &base),
            Plan::key_for(&identity, &base)
        );

        // Handing the same sources over in another order is the same
        // compilation, not a different one.
        let reordered = Request::new(Abi::Arm64V8a, 30)
            .with_source(Source::of("B.kt", b"fun other() {}"))
            .with_source(Source::of("A.kt", b"fun main() {}"));
        assert_eq!(
            Plan::key_for(&identity, &base),
            Plan::key_for(&identity, &reordered),
            "the order sources were handed over in must not decide anything"
        );

        // And everything that does change what comes out has to change the key.
        let mut seen = std::collections::BTreeSet::new();
        seen.insert(Plan::key_for(&identity, &base).to_hex());

        // There is one machine, so there is no second value to vary. What
        // still has to hold is that the machine reaches the key at all, so
        // that naming a second one later cannot land on the first one's
        // artifacts.
        let encoded = base.canonical().encode();
        assert!(
            encoded
                .windows(Abi::Arm64V8a.as_str().len())
                .any(|window| window == Abi::Arm64V8a.as_str().as_bytes()),
            "the machine has to be part of what the key is taken over"
        );

        let mut changed = base.clone();
        changed.api_level = 36;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "api"
        );

        let mut changed = base.clone();
        changed.optimise = !changed.optimise;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "optimise"
        );

        let mut changed = base.clone();
        changed.debug_info = !changed.debug_info;
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "debug info"
        );

        let mut changed = base.clone();
        changed.dependencies.push(super::hash::sha256(b"a library"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "dependencies"
        );

        let mut changed = base.clone();
        changed
            .options
            .push(("jvmTarget".to_string(), "25".to_string()));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "options"
        );

        let changed = Request::new(Abi::Arm64V8a, 28)
            .with_source(Source::of("A.kt", b"fun main() { }"))
            .with_source(Source::of("B.kt", b"fun other() {}"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "source bytes"
        );

        let changed = Request::new(Abi::Arm64V8a, 28)
            .with_source(Source::of("Renamed.kt", b"fun main() {}"))
            .with_source(Source::of("B.kt", b"fun other() {}"));
        assert!(
            seen.insert(Plan::key_for(&identity, &changed).to_hex()),
            "source name"
        );

        // A different compiler is a different compilation, however identical
        // everything else is. This is what makes upgrading one invalidate what
        // the old one built instead of quietly serving it.
        for moved in [
            Identity::new("kotlin", "omni.kotlin", "2.4.11", "aarch64-linux-android"),
            Identity::new("kotlin", "other.kotlin", "2.4.10", "aarch64-linux-android"),
            Identity::new("java", "omni.kotlin", "2.4.10", "aarch64-linux-android"),
            Identity::new("kotlin", "omni.kotlin", "2.4.10", "aarch64-linux-android30"),
            identity.clone().with("stdlib", "2.4.10"),
        ] {
            assert!(
                seen.insert(Plan::key_for(&moved, &base).to_hex()),
                "{moved:?} planned to a key something else already had"
            );
        }

        eprintln!(
            "contract: {} distinct compilations, no two sharing a key",
            seen.len()
        );
    }

    #[test]
    fn what_a_build_made_is_kept_checked_and_found_again_after_a_restart() {
        let directory = temp_directory("omni-store");
        let root = directory.join("Objects");
        let root_text = root.to_str().unwrap().to_string();
        let store = super::store::Store::at(&root_text);

        // Names come from contents, so the same bytes put twice are one object.
        let one = store.put(b"what the compiler wrote").unwrap();
        let same = store.put(b"what the compiler wrote").unwrap();
        assert_eq!(one, same, "the same bytes must be the same object");
        assert_eq!(store.list().len(), 1, "and must not be kept twice");
        assert_eq!(store.get(one).unwrap(), b"what the compiler wrote");

        let other = store.put(b"and what it wrote next").unwrap();
        assert_ne!(one, other);
        assert!(store.has(other));
        assert_eq!(store.list().len(), 2);

        // Nothing is left behind from staging: an object arrives whole or not
        // at all, and the name it waited under is gone either way.
        let staged = std::fs::read_dir(format!("{root_text}/{}", super::store::STAGING))
            .map(|entries| entries.count())
            .unwrap_or(0);
        assert_eq!(staged, 0, "a finished put leaves nothing staged");

        // Storage that hands back different bytes than it was given is rare
        // and real. An object that no longer hashes to its own name is thrown
        // away and said so, rather than handed to a build that cannot tell.
        let hex = one.to_hex();
        let path = format!("{root_text}/{}/{}", &hex[..2], &hex[2..]);
        std::fs::write(&path, b"not what the compiler wrote at all").unwrap();
        let refused = store
            .get(one)
            .expect_err("an object that does not match its name must be refused");
        assert_eq!(refused.code, "ES010");
        assert!(
            !store.has(one),
            "and it must be gone, so the next build makes it again"
        );

        // Put back, so the rest has something to work with.
        let one = store.put(b"what the compiler wrote").unwrap();

        // A lease holds an object against a sweep, and lasts exactly as long as
        // the lease does.
        let budget = 4u64;
        {
            let held = store.lease(one);
            assert_eq!(held.digest(), one);
            assert!(store.is_leased(one));
            let swept = store.sweep(budget, &std::collections::BTreeSet::new());
            assert!(store.has(one), "a leased object must survive a sweep");
            assert!(swept.held_back >= 1);
        }
        assert!(!store.is_leased(one), "and the hold ends with the lease");

        // Named in `keep`, it survives too.
        let mut keep = std::collections::BTreeSet::new();
        keep.insert(one);
        store.sweep(budget, &keep);
        assert!(store.has(one), "an object asked for must survive a sweep");

        // Nothing holding it, and over budget: it goes.
        let swept = store.sweep(budget, &std::collections::BTreeSet::new());
        assert!(swept.removed >= 1, "{swept:?}");
        assert!(store.total_bytes() <= budget, "{}", store.total_bytes());

        // A store already inside its budget is left entirely alone.
        let before = store.list().len();
        let quiet = store.sweep(u64::MAX, &std::collections::BTreeSet::new());
        assert_eq!(quiet.removed, 0);
        assert_eq!(store.list().len(), before);

        // And now the index across a restart, which is the thing that was
        // missing: an index that could say a key had been seen and could not
        // hand back what was made for it.
        let index_path = directory.join("Index").to_str().unwrap().to_string();
        let made = store.put(b"the package this key stands for").unwrap();
        let source = super::hash::sha256(b"source");
        let dependencies = super::hash::sha256(b"deps");
        let key = cache_inputs(&source, &dependencies).key();

        let mut index = super::cache::Index::new();
        index.record(key, made, 31, 1_787_000_000);
        index.write(&index_path).expect("the index must write");
        assert!(
            !std::path::Path::new(&format!("{index_path}.writing")).exists(),
            "the file written beside it should have been moved over it"
        );

        // A different process, a fresh index, the same folder.
        let reopened = super::cache::Index::read(&index_path);
        assert_eq!(
            reopened.len(),
            1,
            "the index must survive being written down"
        );
        let found = reopened
            .content_for(key)
            .expect("and must still say what the key stands for");
        assert_eq!(found, made);
        assert_eq!(
            store.get(found).unwrap(),
            b"the package this key stands for",
            "which is the whole point: the bytes come back"
        );

        // An index that outlives what it indexes is worse than none, because
        // every lookup says hit and every read then fails.
        store.remove(made).unwrap();
        let mut stale = super::cache::Index::read(&index_path);
        assert_eq!(stale.len(), 1);
        assert_eq!(stale.reconcile(&store), 1, "the dangling entry must go");
        assert_eq!(stale.content_for(key), None);

        // A damaged index is an empty index, not a failure. Refusing to start
        // because a cache file got damaged would turn something harmless into
        // something fatal.
        std::fs::write(&index_path, b"this is not an index").unwrap();
        assert!(super::cache::Index::read(&index_path).is_empty());
        std::fs::write(&index_path, []).unwrap();
        assert!(super::cache::Index::read(&index_path).is_empty());
        assert!(super::cache::Index::read("nowhere at all").is_empty());

        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "store: content-addressed, moved into place, checked on the way out, \
             swept by lease and budget, and found again after a restart"
        );
    }

    #[test]
    fn two_different_projects_never_come_to_one_digest() {
        use super::canonical::Record;

        // The collision that was actually there. Joining a feature name to its
        // value with `=` means these two are the same string, so they were the
        // same digest, so a build of one could be served out of the cache for
        // the other.
        let mut one = super::project::Project::defaults("App", "com.my.app");
        one.features = vec![("a=b".to_string(), true)];
        let mut other = super::project::Project::defaults("App", "com.my.app");
        other.features = vec![("a".to_string(), true), ("b".to_string(), true)];
        assert_ne!(
            one.digest(),
            other.digest(),
            "a feature called `a=b` and the features `a` and `b` must not share a digest"
        );

        // The other half of the same problem: order carried meaning where it
        // had none, so listing two features the other way round was a miss and
        // a rebuild for nothing.
        let mut forwards = super::project::Project::defaults("App", "com.my.app");
        forwards.features = vec![("alpha".to_string(), true), ("beta".to_string(), false)];
        let mut backwards = super::project::Project::defaults("App", "com.my.app");
        backwards.features = vec![("beta".to_string(), false), ("alpha".to_string(), true)];
        assert_eq!(
            forwards.digest(),
            backwards.digest(),
            "the same features in another order are the same project"
        );

        // The name is what a person calls it and changes nothing that is built.
        let renamed = super::project::Project::defaults("Something Else", "com.my.app");
        assert_eq!(
            super::project::Project::defaults("App", "com.my.app").digest(),
            renamed.digest(),
            "renaming a project must not throw its cache away"
        );

        // The edition decides how the source is read, so it must be in there.
        let mut with_edition = super::project::Project::defaults("App", "com.my.app");
        with_edition.edition = Some("2021".to_string());
        let mut other_edition = super::project::Project::defaults("App", "com.my.app");
        other_edition.edition = Some("2024".to_string());
        assert_ne!(with_edition.digest(), other_edition.digest());
        assert_ne!(
            with_edition.digest(),
            super::project::Project::defaults("App", "com.my.app").digest(),
            "an edition set at all is not the same as none"
        );

        // Every switch has to reach the digest, or a build with it flipped
        // comes back out of the cache built without it.
        let base = super::project::Project::defaults("App", "com.my.app");
        let mut seen = std::collections::BTreeSet::new();
        seen.insert(base.digest().to_hex());
        for change in 0..9usize {
            let mut moved = base.clone();
            match change {
                0 => moved.lto = !moved.lto,
                1 => moved.incremental = !moved.incremental,
                2 => moved.parallel = !moved.parallel,
                3 => moved.deterministic = !moved.deterministic,
                4 => moved.provenance = !moved.provenance,
                5 => moved.verification = !moved.verification,
                6 => moved.min_sdk += 1,
                7 => moved.target_sdk += 1,
                _ => moved.compile_sdk += 1,
            }
            assert!(
                seen.insert(moved.digest().to_hex()),
                "change {change} did not reach the digest"
            );
        }

        // And the encoding is injective because it can be read back, which is
        // the same claim said in a way that can be tested.
        let mut record = Record::new();
        record
            .text("name", "value")
            .text("nam", "evalue")
            .bytes("empty", b"")
            .number("count", 7)
            .flag("on", true);
        let written = record.encode();
        let read = super::canonical::decode(&written).expect("what was written must read back");
        assert_eq!(read.len(), 5);
        assert_eq!(
            super::canonical::decode(&written[..written.len() - 1]),
            None,
            "a truncated encoding must not read as a shorter one"
        );

        // `name`=`value` and `nam`=`evalue` join to the same string and must
        // not come to the same bytes.
        let mut confusable = Record::new();
        confusable.text("name", "value");
        let mut also = Record::new();
        also.text("nam", "evalue");
        assert_ne!(confusable.encode(), also.encode());

        eprintln!("canonical: features, editions and every switch reach the digest, none collide");
    }

    #[test]
    fn a_signature_is_blinded_and_still_comes_out_the_same_bytes_every_time() {
        // Blinding draws fresh randomness for every signature. If any of it
        // reached the answer, two signatures over one digest would differ, and
        // a build would stop being reproducible -- which is a promise this
        // project makes and a test elsewhere holds it to. So the first thing to
        // prove is that none of it does.
        let key = super::rsa::generate(2048).expect("a key must be made");
        let digest = super::hash::sha256(b"the same thing, signed again and again");

        let first =
            super::rsa::sign_digest(&key, super::rsa::DigestAlgorithm::Sha256, digest.as_bytes())
                .expect("the first signature");
        for round in 0..6 {
            let again = super::rsa::sign_digest(
                &key,
                super::rsa::DigestAlgorithm::Sha256,
                digest.as_bytes(),
            )
            .expect("and every one after");
            assert_eq!(
                first, again,
                "round {round} produced different bytes, so the blinding leaked into the answer"
            );
        }

        // And it verifies, which is what says the blinding divided back out
        // rather than being lost somewhere.
        super::rsa::verify(
            key.modulus(),
            key.public_exponent(),
            super::rsa::DigestAlgorithm::Sha256,
            digest.as_bytes(),
            &first,
        )
        .expect("a blinded signature must verify like any other");

        // The same key without its CRT parts takes the other path through the
        // exponentiation, where the order is (p-1)(q-1) rather than either
        // prime's. Getting that wrong gives a different answer, not the same
        // one by another route, so this is where it would show.
        let plain = key.without_crt();
        let without_crt = super::rsa::sign_digest(
            &plain,
            super::rsa::DigestAlgorithm::Sha256,
            digest.as_bytes(),
        )
        .expect("the whole exponent must sign too");
        assert_eq!(
            first, without_crt,
            "the two routes through the exponentiation must agree"
        );

        // A key with no public exponent has nothing to build a blinding on, and
        // nothing here signs unblinded.
        let blind_less = key.without_public_exponent();
        assert_eq!(
            super::rsa::sign_digest(
                &blind_less,
                super::rsa::DigestAlgorithm::Sha256,
                digest.as_bytes()
            )
            .expect_err("signing without anything to blind with must be refused")
            .code,
            "ER024"
        );

        eprintln!("rsa: seven signatures over one digest, blinded afresh each time, all identical");
    }

    #[test]
    fn the_substitution_is_computed_and_answers_what_the_table_would() {
        // The table is the one the standard describes. Nothing that touches a
        // key reads it; it is built here so that every one of the 256 bytes can
        // be put through both and held to the same answer. If the arithmetic
        // ever drifts from the standard, this says so before a vector does.
        let (sbox, inverse) = super::cipher::table_substitution();

        for value in 0..=255u8 {
            let (forward, backward) = super::cipher::computed_substitution(value);
            assert_eq!(
                forward, sbox[value as usize],
                "substituting {value:#04x} computed {forward:#04x}, the table says {:#04x}",
                sbox[value as usize]
            );
            assert_eq!(
                backward, inverse[value as usize],
                "undoing {value:#04x} computed {backward:#04x}, the table says {:#04x}",
                inverse[value as usize]
            );
        }

        // And the two undo one another, which the tables above cannot prove on
        // their own because one is built from the other.
        for value in 0..=255u8 {
            let (forward, _) = super::cipher::computed_substitution(value);
            let (_, back) = super::cipher::computed_substitution(forward);
            assert_eq!(back, value, "{value:#04x} did not survive the round trip");
        }

        eprintln!("cipher: 256 bytes substituted by arithmetic, none by table lookup");
    }

    #[test]
    fn a_tag_is_compared_without_saying_where_it_parted() {
        assert!(super::cipher::same_bytes(b"", b""));
        assert!(super::cipher::same_bytes(&[1, 2, 3], &[1, 2, 3]));
        assert!(!super::cipher::same_bytes(&[1, 2, 3], &[1, 2]));
        assert!(!super::cipher::same_bytes(&[1, 2, 3], &[9, 2, 3]));
        assert!(!super::cipher::same_bytes(&[1, 2, 3], &[1, 2, 9]));

        // Every single-byte difference, at every position, has to be found.
        let base = [0x5au8; 32];
        for position in 0..base.len() {
            for flip in 1..=255u8 {
                let mut other = base;
                other[position] ^= flip;
                assert!(
                    !super::cipher::same_bytes(&base, &other),
                    "a difference at byte {position} was missed"
                );
            }
        }
    }

    #[test]
    fn aes256_matches_the_fips_197_vector() {
        let key: [u8; 32] =
            bytes_of("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f")
                .try_into()
                .unwrap();
        let plain: [u8; 16] = bytes_of("00112233445566778899aabbccddeeff")
            .try_into()
            .unwrap();
        let cipher = super::cipher::encrypt_ecb_block(&key, &plain);
        assert_eq!(hex_string(&cipher), "8ea2b7ca516745bfeafc49904b496089");
    }

    #[test]
    fn aes256_cbc_matches_the_nist_special_publication_vectors() {
        let key: [u8; 32] =
            bytes_of("603deb1015ca71be2b73aef0857d77811f352c073b6108d72d9810a30914dff4")
                .try_into()
                .unwrap();
        let iv: [u8; 16] = bytes_of("000102030405060708090a0b0c0d0e0f")
            .try_into()
            .unwrap();
        let plain = bytes_of(concat!(
            "6bc1bee22e409f96e93d7e117393172a",
            "ae2d8a571e03ac9c9eb76fac45af8e51",
            "30c81c46a35ce411e5fbc1191a0a52ef",
            "f69f2445df4f9b17ad2b417be66c3710"
        ));
        let expected = concat!(
            "f58c4c04d6e5f1ba779eabfb5f7bfbd6",
            "9cfc4e967edb808d679f777bc6702c7d",
            "39f23369a9d9bacfa530e26304231461",
            "b2eb05e2c39be9fcda6c19078c6a9d1b"
        );
        let produced = super::cipher::encrypt_cbc(&key, &iv, &plain);
        assert_eq!(hex_string(&produced[..64]), expected);

        let back = super::cipher::decrypt_cbc(&key, &iv, &produced).unwrap();
        assert_eq!(back, plain);
    }

    #[test]
    fn hmac_matches_the_rfc_4231_vectors() {
        let cases: &[(&str, &str, &str, &str)] = &[
            (
                "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b",
                "4869205468657265",
                "b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7",
                "87aa7cdea5ef619d4ff0b4241a1d6cb02379f4e2ce4ec2787ad0b30545e17cdedaa833b7d6b8a702038b274eaea3f4e4be9d914eeb61f1702e696c203a126854",
            ),
            (
                "4a656665",
                "7768617420646f2079612077616e7420666f72206e6f7468696e673f",
                "5bdcc146bf60754e6a042426089575c75a003f089d2739839dec58b964ec3843",
                "164b7a7bfcf819e2e395fbe73b56e0a387bd64222e831fd610270cd7ea2505549758bf75c05a994a6d034f65f8f0e6fdcaeab1a34d4a6b4b636e070a38bce737",
            ),
        ];
        for (key, message, expected256, expected512) in cases {
            let key = bytes_of(key);
            let message = bytes_of(message);
            assert_eq!(
                hex_string(&super::cipher::hmac_sha256(&key, &message)),
                *expected256
            );
            assert_eq!(
                hex_string(&super::cipher::hmac_sha512(&key, &message)),
                *expected512
            );
        }
    }

    #[test]
    fn pbkdf2_matches_the_published_vectors() {
        let cases: &[(&str, &str, u32, usize, &str)] = &[
            (
                "password",
                "salt",
                1,
                32,
                "120fb6cffcf8b32c43e7225256c4f837a86548c92ccc35480805987cb70be17b",
            ),
            (
                "password",
                "salt",
                2,
                32,
                "ae4d0c95af6b46d32d0adff928f06dd02a303f8ef3c251dfd6e2d85a95474c43",
            ),
            (
                "password",
                "salt",
                4096,
                32,
                "c5e478d59288c841aa530db6845c4c8d962893a001ce4e11a4963873aa98134a",
            ),
            (
                "passwordPASSWORDpassword",
                "saltSALTsaltSALTsaltSALTsaltSALTsalt",
                4096,
                40,
                "348c89dbcbd32b2f32d814b8116e84cf2b17347ebc1800181c4e2a1fb8dd53e1c635518c7dac47e9",
            ),
        ];
        for (password, salt, iterations, length, expected) in cases {
            let derived = super::cipher::pbkdf2_sha256(
                password.as_bytes(),
                salt.as_bytes(),
                *iterations,
                *length,
            )
            .unwrap();
            assert_eq!(
                hex_string(&derived),
                *expected,
                "{password}/{salt}/{iterations}"
            );
        }
    }

    #[test]
    fn a_wrong_password_returns_nothing_rather_than_rubbish() {
        let key = [0x11u8; 32];
        let other = [0x22u8; 32];
        let iv = [0x33u8; 16];
        let secret = b"a private key would be here";
        let sealed = super::cipher::encrypt_cbc(&key, &iv, secret);

        assert_eq!(
            super::cipher::decrypt_cbc(&key, &iv, &sealed).unwrap(),
            secret
        );
        let error = super::cipher::decrypt_cbc(&other, &iv, &sealed).unwrap_err();
        assert_eq!(error.code, "EK002");
    }

    #[test]
    fn the_cipher_round_trips_every_length_across_the_block_boundary() {
        let key = [0x5au8; 32];
        let iv = [0xa5u8; 16];
        for length in 0..80usize {
            let plain: Vec<u8> = (0..length).map(|at| (at * 7 % 251) as u8).collect();
            let sealed = super::cipher::encrypt_cbc(&key, &iv, &plain);
            assert!(sealed.len() > length, "padding must always be added");
            assert!(sealed.len().is_multiple_of(16));
            assert_eq!(
                super::cipher::decrypt_cbc(&key, &iv, &sealed).unwrap(),
                plain,
                "length {length}"
            );
        }
    }

    #[test]
    fn a_developer_key_is_sealed_with_their_password_and_openssl_opens_it() {
        let key = super::rsa::generate(1024).expect("a key must be made");
        let password = "correct horse battery";
        let sealed = super::rsa::seal_pkcs8(&key, password).expect("the key must seal");

        let reopened = super::rsa::open_pkcs8(&sealed, password).expect("our own key must open");
        assert_eq!(reopened.modulus(), key.modulus());

        let wrong = super::rsa::open_pkcs8(&sealed, "not the password").unwrap_err();
        assert_eq!(wrong.code, "EK002");

        // One wrong password in every two hundred and fifty six decrypts to
        // something whose last byte passes for padding, and what is left is
        // read rather than rejected. It is still a wrong password: whatever
        // the reading makes of it, one answer comes back.
        let bad = super::rsa::open_pkcs8(&sealed, "wrong in another way").unwrap_err();
        assert_eq!(bad.code, "EK002");

        let Some(tool) = openssl() else {
            eprintln!("keystore conformance: openssl is not available here");
            return;
        };
        let directory = temp_directory("omni-keystore");
        let path = directory.join("developer.pk8");
        std::fs::write(&path, &sealed).unwrap();

        let opened = std::process::Command::new(&tool)
            .args([
                "pkcs8",
                "-topk8",
                "-inform",
                "DER",
                "-in",
                path.to_str().unwrap(),
                "-passin",
                &format!("pass:{password}"),
                "-nocrypt",
                "-outform",
                "DER",
                "-out",
                directory.join("plain.pk8").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            opened.status.success(),
            "openssl could not open a key this build sealed: {}",
            String::from_utf8_lossy(&opened.stderr)
        );
        let plain = std::fs::read(directory.join("plain.pk8")).unwrap();
        let theirs = super::rsa::parse_pkcs8(&plain).unwrap();
        assert_eq!(theirs.modulus(), key.modulus());

        let refused = std::process::Command::new(&tool)
            .args([
                "pkcs8",
                "-topk8",
                "-inform",
                "DER",
                "-in",
                path.to_str().unwrap(),
                "-passin",
                "pass:wrong",
                "-nocrypt",
                "-out",
                directory.join("no.pk8").to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            !refused.status.success(),
            "a wrong password must not open it"
        );

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("keystore conformance: openssl opened a PBES2 key this build sealed, and refused the wrong password");
    }

    #[test]
    fn a_short_password_is_refused_before_a_key_is_written() {
        let key = super::rsa::generate(1024).unwrap();
        let error = super::rsa::seal_pkcs8(&key, "short").unwrap_err();
        assert_eq!(error.code, "ER040");
        assert!(error.suggestion.unwrap().contains("only thing between"));
    }

    #[test]
    fn every_attribute_identifier_is_the_one_aapt2_uses() {
        let (Some(aapt2), Some(jar)) = (find_build_tool("aapt2"), android_jar()) else {
            eprintln!("axml conformance: aapt2 or android.jar is not available here");
            return;
        };

        let directory = temp_directory("axml-ids");
        let source = directory.join("AndroidManifest.xml");
        std::fs::write(&source, ATTRIBUTE_PROBE_MANIFEST).unwrap();

        let out = directory.join("probe.apk");
        let linked = std::process::Command::new(&aapt2)
            .args([
                "link",
                "--manifest",
                source.to_str().unwrap(),
                "-o",
                out.to_str().unwrap(),
                "-I",
                jar.to_str().unwrap(),
            ])
            .output()
            .unwrap();
        assert!(
            linked.status.success(),
            "aapt2 link failed: {}",
            String::from_utf8_lossy(&linked.stderr)
        );

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                out.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let text = String::from_utf8_lossy(&dumped.stdout).to_string();

        for (name, id) in axml::ATTRIBUTES {
            let marker = format!("android:{name}(0x{id:08x})");
            assert!(
                text.contains(&marker),
                "aapt2 does not agree that {name} is 0x{id:08x}"
            );
        }
        std::fs::remove_dir_all(&directory).ok();
        eprintln!(
            "axml conformance: {} attribute identifiers agree with aapt2",
            axml::ATTRIBUTES.len()
        );
    }

    #[test]
    fn the_binary_xml_this_build_writes_is_read_by_aapt2() {
        let (root, sink) = parse_xml(PROBE_MANIFEST);
        assert!(!sink.has_blocking(), "{:?}", sink.entries());
        let root = root.expect("the manifest must parse");
        let encoded = axml::encode(&root).expect("the manifest must encode");

        let Some(aapt2) = find_build_tool("aapt2") else {
            assert!(
                std::env::var("OMNI_REQUIRE_AXML_CONFORMANCE").is_err(),
                "OMNI_REQUIRE_AXML_CONFORMANCE is set but aapt2 is missing, so the \
                 manifest this build writes was never checked against it"
            );
            eprintln!("axml conformance: aapt2 is not available here");
            return;
        };

        let mut builder = ArchiveBuilder::for_android();
        builder.add("AndroidManifest.xml", encoded).unwrap();
        let apk = builder.finish().unwrap();

        let directory = temp_directory("axml-dump");
        let path = directory.join("ours.apk");
        std::fs::write(&path, &apk).unwrap();

        let dumped = std::process::Command::new(&aapt2)
            .args([
                "dump",
                "xmltree",
                path.to_str().unwrap(),
                "--file",
                "AndroidManifest.xml",
            ])
            .output()
            .unwrap();
        let text = String::from_utf8_lossy(&dumped.stdout).to_string();
        assert!(
            dumped.status.success(),
            "aapt2 refused what this build wrote: {}\n{text}",
            String::from_utf8_lossy(&dumped.stderr)
        );

        let expected = [
            "N: android=http://schemas.android.com/apk/res/android",
            "E: manifest",
            "A: package=\"com.omni.probe\"",
            "E: uses-sdk",
            "android:minSdkVersion(0x0101020c)=30",
            "android:targetSdkVersion(0x01010270)=36",
            "E: uses-permission",
            "android:name(0x01010003)=\"android.permission.INTERNET\"",
            "E: application",
            "android:label(0x01010001)=\"Omni\"",
            "android:allowBackup(0x01010280)=false",
            "android:supportsRtl(0x010103af)=true",
            "android:extractNativeLibs(0x010104ea)=false",
            "android:theme(0x01010000)=@0x7f060000",
            "E: activity",
            "android:name(0x01010003)=\"com.omni.probe.Main\"",
            "android:exported(0x01010010)=true",
        ];
        for line in expected {
            assert!(
                text.contains(line),
                "aapt2 did not report {line:?}:\n{text}"
            );
        }

        std::fs::remove_dir_all(&directory).ok();
        eprintln!("axml conformance: aapt2 read the binary XML this build wrote");
    }

